import type { MeaningPack } from '../../types';
export const taHksA: MeaningPack = {
  lang: 'ta',
  texts: {
    'harikathamrutasara-04': {
      summary: "நான்காம் சந்தி (போஜனரஸ விபாகம்): ஒவ்வொரு உயிரும் உண்ணும் உணவிலும் அதன் சுவைகளிலும் ஹரி வாஸுதேவன், ஸங்கர்ஷணன், ப்ரத்யும்னன், அநிருத்தன், நாராயணன் எனப் பல வடிவங்களில் உறைகிறான்; அவ்வடிவங்களின் எண்ணிக்கையை இச்சந்தி கணக்கிட்டுக் கூறுகிறது. இதை அறிந்து உணவை ஹரிக்கு அர்ப்பணித்து உண்பவன் நித்திய மகா யாகங்களைச் செய்தவன் போன்றவன்; ஹரி பக்தனின் அர்ப்பணத்தை அன்புடன் ஏற்கிறான்; தான் உண்பதனால் ஒருபோதும் விகாரமடைவதில்லை.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருத ஸாரத்தைக் கூறுகிறேன்; உயர்ந்த பகவத் பக்தர்களே, இதை மரியாதையுடன் கேளுங்கள். (ஒவ்வொரு சந்தியின் தொடக்கத்திலும் பாடப்படும் பல்லவி.)",
        '0.1': "பிரம்மாண்டத்திலுள்ள எல்லா உயிர்களும் நான்கு வகை உணவை உண்கின்றன; அவற்றில் நான்கு வகைச் சுவை வடிவாக இருக்கும் ஹரி மனம் விரும்பியதை உண்ணச் செய்து, உடலுக்கு வளர்ச்சியையும், புலன்களுக்கு மகிழ்ச்சியையும், தேவர்களுக்குத் தன் தரிசனச் சுகத்தையும் அளிக்கிறான்.",
        '0.2': "ஜீவனுக்குக் கூடு போன்ற சூக்ஷ்ம உடலுக்கு (லிங்கத்துக்கு) உணவின் சாரத்தைப் பதினாறு பங்காக்கி, அதன் பதினாறு கலைகளுக்கு வளர்ச்சி அளித்து, ஆனந்த வடிவினனான ஹரி உடலிலுள்ள எழுபத்தீராயிரம் நாடிகளின் தேவதைகளுக்குள் இருந்து சஞ்சரிக்கிறான். (இப்பாடலின் பாடம் முழுமையாகச் சரிபார்க்கப்படவில்லை.)",
        '0.3': "நீர் என்ற சொல்லால் குறிக்கப்படும் ஹரி, ரஸம் எனப்படும் நீரில் உறைந்து, ஆண் பெண்களின் முப்பத்தாறாயிரம் நாடிகளில் அந்த வடிவைத் தாங்கி, உடல் முழுவதும் இரவும் பகலும் விளையாடுகிறான்; அவனுக்கு 'ப்ருஹதி' என்ற நற்பெயர் உண்டு.",
        '0.4': "ஆறு சுவைகள் ஸத்வம் முதலிய குண வேறுபாட்டால் பதினெட்டாகின்றன; அவை சாரம்-அசாரம், ஏற்பது-விடுவது, துண்டு-முழுமை என மேலும் பிரிகின்றன. உடலிலும் நல்ல உணவுப் பொருள்களிலும் 'ரஸம்' என்ற பெயருள்ள ரமாபதியின் எழுபத்தீராயிரம் வடிவங்கள் உள்ளன என அறிந்து உண்ண வேண்டும்.",
        '0.5': "பாலில் ரஸ வடிவங்கள் 354, நெய்யில் 29, வெல்லத்தில் 5,101, பழங்களில் 2,225 என்று இப்பாடல் கூறுகிறது (அந்தந்தப் பொருளில் ரஸ வடிவான ஹரியின் வடிவங்களின் எண்ணிக்கை).",
        '0.6': "தெளிவான, உறுதியான, கூர்மையான சுவைகளில் 15,309 வடிவங்கள் உள்ளன; அவற்றை நினைத்து உண்ண வேண்டும். விஷயங்களுக்கும் தத்துவங்களுக்கும் அதிபதிகளுக்குள் இருக்கும் ஹரி இப்பெயர்களால் அழைக்கப்படுகிறான்; இவ்வாறு அறிந்து தியானிக்கும் ஞானிகளின் மனத்தில் அவன் ஒளிர்கிறான்.",
        '0.7': "கண், மூக்கு, வாயில் கபிலர், நரஹரி, பரசுராமர் என்ற வடிவங்களாக; நாக்கில் மத்ஸ்ய வடிவாக; பற்களில் ஹம்ஸ வடிவாக; மூன்றடிக் காயத்ரி, செய்யுள் வடிவான வாக்கில் ஹயக்ரீவ வடிவாக ஹரி உள்ளான். அளவற்ற இன்பம் நிறைந்த அவன் எளியவர்களிடமும் இருந்து அவரவருக்குரிய சுவையை ஏற்றுக் கொடுக்கிறான்.",
        '0.8': "ஒப்பற்ற ஆனந்த வடிவினனான ஹரி ஸங்கர்ஷணன், ப்ரத்யும்னன் என்ற வடிவங்களால் உண்பவர்களுக்குள் அவர்களின் ஆற்றலாக இருக்கிறான்; நாராயணன், அநிருத்தன் என்ற இரு பெயர்களால் உணவுப் பொருள்களில் இருந்து திருப்தி தருபவனாக ஜீவனுக்கு நிறைவளிக்கிறான்.",
        '0.9': "வாஸுதேவன் உள்ளும் புறமும் இடம் தரும் ஆகாயத்தில் இருப்பவனாகி ஐந்து வடிவங்களில் ரமையுடன் விளையாடுகிறான். பிரம்மா, சிவன், இந்திரன் முதலிய தேவர்கள் உட்பட எல்லா உயிர்த் தொகைக்குள்ளும் அவன் இருக்கிறான் என்று அறிந்தவனே உண்மையான ஞானி.",
        '0.10': "வாஸுதேவன் சோற்றிலும் பலவகை நல்ல பண்டங்களிலும்; ஸங்கர்ஷணன் பாயசத்திலும்; அநிருத்தன் நெய்யிலும்; கருடவாகனன் பருப்புக் குழம்பிலும்; இந்திரனின் தம்பி உபேந்திரன் காய்கறியிலும் உள்ளனர்; இவ்வாறு மூலரூபமான நாராயணன் எங்கும் நிலைத்திருக்கிறான்.",
        '0.11': "எண்ணற்ற நல்ல உணவுப் பொருள்களில் ஒவ்வொன்றிலும் முழுமையாக இருந்தும் எல்லையற்ற அம்சங்களால் பகுதிகளாகக் கூறப்படுபவனும், உலக உயிர்களைத் திருப்தி செய்பவனும், உள்ளார்ந்த பேதம் இல்லாதவனுமான ஹரியின் இவ்விரு வடிவங்களை அறிந்து, அவனுக்கு அர்ப்பணித்து உண்ணுங்கள்.",
        '0.12': "இவ்வாறு அறிந்து உண்பவன் எப்போதும் உபவாசி போன்றவன், நோயற்றவன், பாவமற்றவன்; நித்திய மகா யாகங்களைச் செய்தவன். 'போவதும் இருப்பதும் வருவதும் எல்லாம் ரமாபதியின் இருப்பிடம்' என்று அவன் சொன்னால் கருணைக்கடலான ஹரி தாயைப் போல அவன் சொல்லைக் கேட்கிறான்.",
        '0.13': "பரம போக்தாவான அநிருத்தன் 12,251 வடிவங்களால் 'அன்னமயன்' எனப்படுகிறான்; ப்ரத்யும்னன் 6,043 வடிவங்களால் உலகில் 'ப்ராணமயனாகத்' தோன்றுகிறான்.",
        '0.14': "ஸங்கர்ஷணன் இரு கோசங்களின் உள்ளும் புறமும் இருந்து 5,62,107 வடிவங்களைத் தாங்கி 'மனோமயன்' எனப்படுகிறான்; அறியாதவர்களுக்கு எட்டாதவன். (அடுத்த பாடலில் வாஸுதேவன் 'விஜ்ஞானமயன்' எனக் கூறப்படுகிறான்.)",
        '0.15': "வாஸுதேவன் 4,374 வடிவங்களால் 'விஜ்ஞானமயன்' என்ற பெயருடன் மஹத் முதலிய தத்துவங்களிலும் அவற்றின் அதிபதிகளிலும் வியாபித்திருக்கிறான். ரமாவும் பிரம்ம அபரோக்ஷம் (நேரடி உணர்வு) பெற்றவர்களின் லிங்க, ஸ்தூல உடல்களை அழித்து முக்தி அளிக்கிறாள்.",
        '0.16': "நாராயணன் 5,125 வடிவங்களைத் தாங்கித் தினமும் 'ஆனந்தமயன்' எனப்படுகிறான்; 5,85,400 வடிவங்களால் ஐந்து கோசங்களை உடைய பிரம்மாண்டத்தில் நிறைந்திருக்கிறான்.",
        '0.17': "சாந்தியின் நாயகனான ஹரி 101 நல்ல வடிவங்களால் 'அன்னம்' எனப்படுகிறான்; ப்ராணன் என்ற பெயருள்ள ப்ரத்யும்னன் 513 வடிவங்களால் தோன்றுகிறான்; மனத்தின் விகாரங்களில் ஸங்கர்ஷணன் 55 வடிவங்களால் தோன்றுகிறான்; விஜ்ஞானாத்மாவான 'விஸ்வன்' என்ற பெயருடையவன் 584 வடிவங்களால் தோன்றுகிறான்.",
        '0.18': "3,052 வடிவங்களைத் தாங்கி நாராயணன் என்ற பெயருடையவன் உடலுக்குள் ஆனந்தமயனாக இருக்கிறான்; 4,305 வடிவங்களால் பாரதீசனான வாயுவுக்குள் வெண்ணெயில் நெய் போல இருக்கிறான்.",
        '0.19': "உடலுக்குள் ப்ராண வாயுவில் அநிருத்தன் 53 வடிவங்களால்; அபானத்தில் ப்ரத்யும்னன் 511 வடிவங்களால்; வ்யானத்தில் ஸங்கர்ஷணன்; உதானத்தில் மாயையின் தலைவனான வாஸுதேவன் 535 வடிவங்களால் உள்ளனர்.",
        '0.20': "மூல நாராயணனான ஸர்வேசன் 557 வடிவங்களைத் தாங்கி ஸமான வாயுவில் எங்கும் இருக்கிறான்; 1,711 வடிவங்களால் ஐந்து பிராணன்களில் இருந்து விளையாட்டாகவே உலகங்களைக் காக்கிறான்.",
        '0.21': "தொண்ணூற்று மூன்று வடிவங்களுடைய அநிருத்தன் எப்போதும் யஜமானனாக இருந்து அக்னி, யமன், சோமன் முதலிய பித்ரு தேவதைகளுக்கு அன்னமாகிய ப்ரத்யும்ன-ஸங்கர்ஷண பாகங்களைப் பிரித்துக் கொடுத்து, தான் துர்யன் (வாஸுதேவன்) என்ற பெயரால் நித்திய ஆனந்த போஜனம் தருபவனாக உண்கிறான்.",
        '0.22': "தொண்ணூற்றாறு பெயர்கள் கொண்ட வசு (வாஸுதேவன்) சூரியனுக்குள் நின்று, சரணடைந்தவர்கள் தினமும் கபடமற்ற நற்பக்தியுடன் செய்யும் புண்ணிய கருமத்தை ஏற்று, அக்கருணைக்கடல் பித்ருக்களுக்கு அளவற்ற சுகம் அளித்துச் செய்தவர்களை எப்போதும் காக்கிறான்.",
        '0.23': "அநிருத்தன் உடலின் தாதுக்களுக்குள் எப்போதும் இருந்து ஐம்பத்தொன்று (வர்ணங்கள்), கரணங்கள், இருபத்துநான்கு தத்துவங்கள் மூலம் உலக உயிர்த் தொகைகளைப் பேணுகிறான்; தொண்ணூற்றாறு பெயர்கள் கொண்ட திறமையான வடிவங்களை வழிபடுபவர்கள் அதனாலேயே வல்லவர்களாகிறார்கள். (இப்பாடலின் பாடம் ஓரளவே தெளிவு.)",
        '0.24': "பிரம்மாண்டத்தையே வயிற்றில் தாங்கிய ஹரி காட்டில் சபரியின் எச்சிற் பழங்களை உண்டான்; கோகுலத்துக் கோபியரை மகிழ்வித்தான்; ரிஷிபத்தினிகள் கொடுத்த அன்னத்தை உண்டான்; கூனியின் சந்தனத்தில் மகிழ்ந்தான். முனிவர் கூட்டங்களும் தேவர்களும் சேவிக்கும் அவன் நாம் அர்ப்பணிக்கும் கர்மப் பலனை விட்டுவிடுவானா?",
        '0.25': "ஹரியின் எண்ணற்ற பரம சுகத்திற்கும் நற்குணங்களுக்கும் ஒரு துளிக்குக் கூட ரமை, பிரம்மா, இந்திரன் முதலியோரின் சுகம் ஈடாகாது. உண்ணும்போது தன்னை மறந்து 'கிருஷ்ணார்ப்பணம்' என்று சொன்னால், தாய் உணவு நேரத்தில் குழந்தைக்காகக் கை நீட்டுவது போல அவன் மகிழ்ச்சியுடன் ஏற்கிறான். (இப்பாடலின் பாடம் முழுமையாகச் சரிபார்க்கப்படவில்லை.)",
        '0.26': "ஜீவர்கள் செய்த கர்மங்களை விடாமல் ரமாபதியான ஹரி ஏற்று, அவரவர் தகுதிக்கேற்ப எப்போதும் பலன்களை அளிக்கிறான். அக்னி எல்லாவற்றையும் உண்டும் விகாரமடைவதில்லை; தூய்மையாக்குவனவற்றுக்கும் தூய்மை தருபவனான ஹரி உண்டாலும் மாறுபடாதிருப்பதில் வியப்பென்ன? இதை அறிந்துகொள்.",
        '0.27': "அசுத்தமான நாவுக்கு நல்ல உணவும் நீரும் முதலில் நஞ்சாகத் தோன்றும்; தூய நாவுக்கு எக்காலமும் சுவையாகவே தோன்றும். அழகிய அங்கங்களுடைய அவனுக்கு எல்லாச் சுவைகளும் மங்கலமே; அன்னமயனான அவன் பூதனையின் நஞ்சு கலந்த முலைப்பாலை உண்டவன்; பக்தியுடன் அர்ப்பணித்ததை ஏற்காமல் விடுவானா?",
        '0.28': "என்ன சொல்வது: வாயுதேவன் காளகூட விஷத்தை உண்டு உலகைக் காத்தான்; அவன் தாசன் ஒருவன் 'அமிர்தன்' எனப்பட்டான். லக்ஷ்மீபதி நல்வினை தீவினைகளின் தொகுதியை உண்டாலும் அவனுக்கு ஒருபோதும் ஏற்றத்தாழ்வு இல்லை; ஆகவே உன் சுய விருப்பச் சுவைகளை விட்டு (அடுத்த பாடலில் தொடர்கிறது).",
        '0.29': "இவ்வாறு பல பொருள்களில் அச்யுதனையும் அவனது வடிவங்களையும் பெயர்களையும் மீண்டும் மீண்டும் நினைத்தபடி உண்டும் உண்ணச் செய்தும் இரு; அவன் விஷயங்களை அளிப்பவன், நிலைநிறுத்துபவன், கட்டுப்படுத்துபவன், வியாபித்திருப்பவன் என அறிந்து, புண்ணிய பாவங்களை அவனுக்கு அர்ப்பணித்துப் பற்றற்றிரு. (இப்பாடலின் பாடம் முழுமையாகச் சரிபார்க்கப்படவில்லை.)",
        '0.30': "செய்யுளின் கணக்குப்படி 5,89,000-க்கும் மேற்பட்ட வடிவங்களைத் தாங்கி, உண்பவன் என்றும் உண்ணப்படுவது என்றும் அழைக்கப்படுபவனாக, ஸ்ரீதரனும் துர்கா ரமணனுமான ஜகந்நாத விட்டலன் பாதம் முதல் தலை வரை வியாபித்து எப்போதும் அனைவரையும் காக்கிறான்.",
      },
    },
    'harikathamrutasara-05': {
      summary: "ஐந்தாம் சந்தி (விபூதி): ஹரி விக்ரஹம், சாளக்ராமம், விருந்தினர், துளசி, புனித மரங்கள், குருமார், பூதங்கள், நாள்-காலங்கள் ஆகியவற்றில் உறைகிறான்; அவற்றில் எண்ணற்ற வடிவங்கள் கொள்கிறான். இவற்றிலும் உடலிலும் (உடலே அவன் கோயில், யாககுண்டம், தேர், படகு) அவனை எப்படி வழிபடுவது என்று இச்சந்தி காட்டுகிறது; நான்கு வர்ணங்களில் ஹரி, தேவர்களின் இருப்பைக் கூறுகிறது; பிம்ப-ப்ரதிபிம்ப (மூல வடிவம், அதன் நிழல்) தத்துவத்தை விளக்குகிறது; எல்லாச் செயல்களையும் அவனுக்கு அர்ப்பணிக்க வேண்டும் என்ற அறிவுரையுடன் முடிகிறது.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருத ஸாரத்தைக் கூறுகிறேன்; உயர்ந்த பகவத் பக்தர்களே, இதை மரியாதையுடன் கேளுங்கள். (ஒவ்வொரு சந்தியின் தொடக்கத்திலும் பாடப்படும் பல்லவி.)",
        '0.1': "லக்ஷ்மிபதியின் உயர்ந்த விபூதி வடிவங்களை ஆங்காங்கே கண்டு மனத்தில் சிந்தித்து வியப்புடன் பார். பொது-சிறப்பு, ஒரே இனம்-வேறு இனம், முழுமை-பகுதி என்ற வேறுபாடுகளை அறிந்தவர்களிடமிருந்து தெரிந்துகொள்.",
        '0.2': "அவன் படைத்த பல உயிர்கள் உலகில் திரிகின்றன; அவற்றில் ஒரே இனம், வேறு இனம், பொது, சிறப்பு ஆகிய தன்மைகளை அறிந்து, அந்தந்த இடத்தில் அவனை நிலைநிறுத்தி மகிழ்ந்த மனத்துடன் வழிபடு; எங்கும் நிறைந்தவனின் வடிவங்களைக் கண்டு பூரித்து மகிழ்.",
        '0.3': "அவன் உறையும் இடங்கள்: விக்ரஹம், சாளக்ராமம், பசு, விருந்தினர், புனித துளசி, அரசமரம், சந்நியாசி, வானப்ரஸ்தன், இல்லறத்தான், பிரம்மசாரி, யஜமானன், தன்னவர்-பிறர், பூமி, நீர், நெருப்பு, காற்று, நட்சத்திரங்கள், ஆகாயம், நவகிரகங்கள், யோகம், கரணம், திதி, வளர்பிறை-தேய்பிறை, சங்கிரமணம்.",
        '0.4': "லக்ஷ்மிபதி புடமிட்ட பொன்னில் ஒளிரும் வடிவம் போல தினமும் சாளக்ராமத்தில் உறைகிறான்; 5,535 வடிவங்களால் மலைகளின் அபிமான தேவதைகளுக்குள் எப்போதும் இருக்கிறான்.",
        '0.5': "ஸ்ரீரமணன் விக்ரஹங்களில் 513 வடிவங்களைத் தாங்கி நிலையாக இருக்கிறான். மரத்தைக் கடைந்தால் நெருப்பு தோன்றுவது போல, பக்தியுடன் நோக்குவோருக்கு அவ்விக்ரஹங்களின் தேவதைகளுக்குள் அந்தந்த உருவத்தில் தோன்றுகிறான்.",
        '0.6': "கருவிகளை இயக்குபவனான அவன் பூஜைக் கருவிகளில் 52,114 வடிவங்களால் இருக்கிறான். அவ்வடிவங்களையும் பெயர்களையும் அறிந்து வழிபடுவோரின் பூஜையைத் தாகமுள்ளவன் நீரை ஏற்பது போல ஏற்கிறான்.",
        '0.7': "மூல வடிவான (பிம்ப) ஹரி இவ்வாறு பொன் முதலிய ஜடப்பொருள்களிலும் தேவர்களிலும் தர்மம்-அர்த்தம்-காமத்திலும் மகிழ்ந்து இருக்கிறான் என்று அறி. ஆசைப்படாமல் உலகக் குடும்பத்தலைவன் தினமும் தரும் சிறிதளவு உணவையும் கரடுமுரடான கம்பளியையும் பாக்கியமாகக் கருதி அவன் திருவடிகளைப் பணி.",
        '0.8': "நீரில் 24 வடிவங்களால்; துளசி இலையில் 6,317 வடிவங்களால்; மலரில் 161 வடிவங்களால்; தீபத்தில் 13 வடிவங்களால்; சந்தனம்-மணத்தில் 403 நல்ல வடிவங்களால் ஹரி இருக்கிறான்.",
        '0.9': "நல்ல இதயத்தின் எட்டு இதழ் தாமரையில் நிலைகொண்ட, எல்லாவற்றிலும் உயர்ந்த மகிமையுடைய அவன் இதழ்களில் சஞ்சரித்து உள்ளிருந்து, தீயவர்களுக்குத் தீய புத்தியையும் தீச்செயலையும், நல்லவர்களுக்கு நல்லறிவையும் தர்மத்தின் வளர்ச்சியையும் அளித்தபடி, குற்றமற்றவனாய் இன்பம் நிறைந்தவனாய் இருக்கிறான்.",
        '0.10': "செல்வம், உடல், வீடு, மனைவி, மக்கள், நண்பர் முதலியவற்றிலும்; குணம், மனம், புத்தி, புலன்களிலும்; ஞானம்-கர்மத்திலும் அவன் அந்தந்தப் பெயர்களால் அழைக்கப்படுகிறான்; தன் சத்திய சங்கல்பப்படி எல்லாவற்றையும் எப்போதும் அவனே செய்து செய்விக்கிறான் என்று நினைத்துக்கொண்டிரு.",
        '0.11': "உணர்வு, பொருள், செயல் என்ற இம்மூன்றையும் நற்பக்தியுடன் எங்கும் மறக்காமல் அவனுடையவை என்று பாவி. 'இவனே என்னுடையவன்' என்று தினமும் சேவிக்கும் பக்தர்களுக்குக் கருணையுள்ள காவலன், கஜேந்திரனிடம் அருள் செய்தது போல, தன்னையே அளிக்கிறான்.",
        '0.12': "ஆகாயம் முதலிய பூதங்களில் பூஜைக்கு நல்ல சாதனங்கள் எனப்படும் பொருள்கள் பலவகைப் புதிய வடிவங்களில் தியானத்துக்குக் கிடைக்கின்றன; இவ்வாறு சிந்தித்து எப்போதும் கோவிந்தனை வழிபடு, அவனைக் கண்டு, ஆனந்தத்தால் ஆடி, போற்று.",
        '0.13': "தாமரை நாபனின் வடிவை மனத்தில் நிறுத்தி உறுதியான பக்தியுடன் குளிர், வெயில், மழை, காற்றை என்றும் நிந்திக்காதே. நிலத்தின் மணத்தை நறுமணமாகவும், நீரைச் சுவையாகவும், உருவத்தை தீபமாகவும், காற்றைச் சாமரமாகவும், ஒலியை இசைக்கருவியாகவும் அர்ப்பணித்தால் அவன் மகிழ்கிறான்.",
        '0.14': "உடலின் உறுப்புகளே ரமாரமணனின் சொந்த வீடுகள்; தினசரி தூய்மையே கழுவலும் பெருக்குதலும்; புலன்களே தீபங்கள்; புலன்கள் தம் விஷயங்களுடன் சேர்வதே கட்டில், அதன் இன்பமே படுக்கை, ஆத்ம நிவேதனமே ஆடை என்று பாவித்து அர்ப்பணி.",
        '0.15': "பாவச்செயல்களே பாதுகைகள்; புனித சாஸ்திர உரையாடலே சந்தனப் பூச்சு; மனத்தின் நல்லியல்புகளே துளசி-மலர்கள்; கோபமே தூபம்; பக்தியே அணிகலன்; எங்கும் பரவிய நல்லறிவே குடை; நல்லறிவு தீபம்; குணங்களைக் கூறுவதே ஆரத்தி என்று அர்ப்பணி.",
        '0.16': "மனம், வாக்கு, உடல் ஆகியவற்றின் வலம் வருதலை நாளும் எங்கும் நிறைந்த தாமரைக்கண்ணனுக்கு அர்ப்பணித்து எப்போதும் மகிழ்ந்திரு. அனுபவத்தில் கொண்டுவா; எல்லாச் சாதனங்களிலும் இதுவே முக்கியம். சாதாரண மனிதர்களுக்குச் சொன்னால் புரியாது, அறிந்தவர்களுக்கே புரியும்.",
        '0.17': "நான்கு புருஷார்த்தங்களைப் பெற பதினான்கு உலகங்களிலும், எல்லா சாஸ்திரங்களையும் பார்த்தாலும், வேறு வழிகள் இல்லை. விஷயங்களிலும் புலன்களிலும் வியாபித்து ஒளிரும் லக்ஷ்மிபதிக்கு எல்லாவற்றையும் சமர்ப்பிப்பதே மகா பூஜை, நல்ல வழி.",
        '0.18': "இது ஆத்மிக யாகம்: உடலே குண்டம், புலன்களே நெருப்பு, வந்தடையும் விஷயங்களே சமித்துகள், முயற்சியே காற்று, ஆசையே புகை, இறைவனின் அண்மையே சுடர், சேர்க்கையே எரிதல், பொங்கும் ஆனந்தங்களே தீப்பொறிகள், அப்போது பேசும் சொற்கள் எல்லாம் மந்திரங்கள்.",
        '0.19': "மதுசூதனனின் நகரம் (உடல்): கண்களும் மூக்கும் கிழக்கு வாயில்கள்; வாயும் இரு காதுகளும் தெற்கு-வடக்கு வாயில்கள்; குதமும் உபஸ்தமும் மேற்கு வாயில்கள்; ஆறு தாமரைகள் (ஆறு சக்கரங்கள்) மாளிகை; இதயமே மண்டபம்; மூன்று குணங்களே கலசங்கள்.",
        '0.20': "தாதுக்கள் ஏழு மதில்கள்; நாடிகள் சிறு தெருக்கள்; மதங்கள் மதயானைகளும் அவற்றின் தலைவர்களும்; சுஷும்ணா நாடியே ராஜபாதை; உடலின் ரோமங்கள் காடுகள்; ஐந்து வடிவங்கள் கொண்ட வாயு பாவங்கள் என்ற பகைவர்களை அழிக்கும் வாள்.",
        '0.21': "சூரியன், சந்திரன் முதலானோர் லக்ஷ்மிநாயகனின் அரண்மனை வாயிற்காவலர்; மனத்தின் வெளிப்பாடுகளே காலாட்படை; அனுபவிக்கும் விஷயங்களே நகரச் சந்தைக்கு வரும் சரக்குகள்; ஜீவன் நல்ல வணிகன்; வரியை ஹரியே பெறுகிறான்.",
        '0.22': "மகா பராக்கிரமசாலியின் இல்லத்துக்குப் பத்துப் புலன்களே கண்ணாடி வரிசைகள்; அறியாதவருக்கு எட்டாதவனின் இனிய விளையாட்டுக்கு மனமே மண்டபம்; மீண்டும் மீண்டும் வீசும் மூச்சுகளே சாமரங்கள்; புத்தியே சாமரம் வீசும் பணிப்பெண்; தாமோதரனுக்குச் செய்யும் சாஷ்டாங்க நமஸ்காரங்களே நல்ல உறக்கங்கள்.",
        '0.23': "மாரமணனின் இல்லத்துக்கு வாயே பெரு வாயில்; அதில் கட்டும் தோரணங்கள் மீசையும் தாடியும்; முடிகளே கொடிகள்; நடக்கும் பாதங்கள், கணுக்கால்கள், தொடைகள், நடு வயிறு, நரம்புகளே வீடும் அதன் மேல் தளங்களும்; ஐந்து கோசங்களே மூலைகள்.",
        '0.24': "இந்த உடலே தேர்; நறுமணங்களும் திலகங்களும் கொடி; மனமே சிங்காசனம்; நல்ல புத்தியே கலசம்; நல்ல மனமே கயிறு; குணங்களே மூன்று தண்டுகள்; நல்வினை தீவினை என்ற இரு கர்மங்களே சக்கரங்கள்; பத்துப் புலன்களே மிக வல்ல குதிரைகள்.",
        '0.25': "உடல் தேரில் வாயுதேவன் எப்போதும் தேரோட்டி, லக்ஷ்மிபதி தேர்த்தலைவன் என்று தினமும் அறிந்து, அன்புடன் காற்று, வெயில் முதலியவற்றால் அதைப் பேணியும் இவ்வுடலில் எனது என்ற பற்றை விட்டவனே மகா யோகி.",
        '0.26': "பவம் என்ற கடலில், கர்மப் பெருக்கில் சஞ்சரிக்கும் உடலை நல்ல படகாக்கி, தன்னவருடன் சேர்ந்து, லக்ஷ்மீநாதன் தினமும் அங்கு விளையாடுகிறான் என்று சிந்தித்தால் வாயுவின் தலைவனான ஹரி பவக்கடலைக் கடக்கச் செய்து பரம சுகம் அளிக்கிறான்.",
        '0.27': "கடையிலுள்ள பொருள்கள், ஆண்-பெண்கள், புலன்கள், விளக்கிலும் நெருப்பிலும் இடும் எண்ணெய் முதலிய பொருள்கள் இவை அனைத்தும் பரம பகவானின் கொடை என்று ஒவ்வொரு அடியிலும் மறக்காமல் நினைத்தபடி, மன்னனைப் போல மகிழ்ந்து எங்கும் அச்சமின்றி சஞ்சரி.",
        '0.28': "பிரம்மாண்டமே அழகிய மண்டபம், மேரு மலையே சிங்காசனம், கங்கையே நீராட்டு, திசைகளே ஆடைகள், சொற்களே மந்திரங்கள், மரங்களின் கனி-மலர்-மணம், காற்று, சந்திரன், சூரியனே தீபங்கள், விண்மீன்களே அணிகலன்கள் என்று மனத்தால் அர்ப்பணித்தால் அவன் ஏற்று அருள்கிறான்.",
        '0.29': "பிராமணர்களில் பிரம்மா இருக்கிறார், அவருக்குள் வாஸுதேவன். வாயு, கருடன், சதாசிவன், சேஷன், சூரியன், சந்திரன், காமன், வருணன் முதலிய தேவர்கள் க்ஷத்திரியர்களில் இருக்கிறார்கள்; தங்களுக்குள் உறையும் ஸங்கர்ஷணனைக் கண்டு அவர்கள் மகிழ்கிறார்கள்.",
        '0.30': "வைசியர்களில் பிராண, அபான, வியான, உதானம் முதலிய வாயுக்கள், நாற்பத்தொன்பது மருத்கணங்கள், ருத்திரர்கள், வசுக்கள், பார்வதி, குபேரன், விஷ்வக்சேனன் முதலிய தேவர்கள் இருக்கிறார்கள்; அவர்களுக்குள் ப்ரத்யும்னனை எப்போதும் அன்புடன் தியானிக்க வேண்டும்.",
        '0.31': "சூத்திரர் எனப்படுவோரில் அஸ்வினி தேவர்கள், நிர்ருதி, யமன், தர்மன், யம தூதர்கள், பூமி, காலன், மிருத்யு, சனி முதலியோர் இருக்கிறார்கள்; அறியாதவர்களுக்கு எட்டாத அநிருத்தன் அவர்களுக்குள் இருக்கிறான் என்று அறிந்து அவர்களை மதி.",
        '0.32': "அச்சமற்ற நாராயணன் நான்கு வர்ணங்களிலும் இருந்து அந்தந்த வர்ணத்தின் தர்மங்களையும் நற்செயல்களையும் தான் செய்து செய்விக்கிறான்; எல்லா உயிர்களின் உள்ளும் புறமும் ஊடுருவி இருந்து மகிழ்ந்து தர்ம, அர்த்த, காமம் முதலியவற்றை அளிக்கிறான்.",
        '0.33': "மரணம்-செல்வத்தை விதிப்பவன், தனக்கு மேம்பட்டவனோ ஒத்தவனோ இல்லாதவன், சாம கானத்தாலும் தேவகணங்களாலும் பூஜிக்கப்படுபவன், முக்கூட்டு மலை உச்சியில் உறைபவன், மங்கலப் பெயருடையவன், மதுமதனன், பிருகுராமன், ஹயவதனன் ஆன ஹரி எல்லாப் பொருள்களிலும் நுனி முதல் அடி வரை நிறைந்திருக்கிறான் என்று பிம்ப ரூபத்தில் சிந்தி.",
        '0.34': "கண்ணாடியைக் கையில் பிடித்துப் பார்த்தால் தன் உருவம் இடம்-வலம் மாறி, கண்ணுக்கு இனிமையாகத் தோன்றுவது போல, அநிருத்தனுக்கு இவ்வுலகம் படைக்கப்பட்டதால் வெவ்வேறாகத் தோன்றுகிறது. இது மூல வடிவான ஹரியின் பிரதிபிம்பம் என்று அறிந்து வழிபட்டால் அவன் ஏற்கிறான். (பிரதிபிம்பம்: மூலத்தையே முழுவதும் சார்ந்த நிழல்வடிவம்.)",
        '0.35': "தன்னைவிட உயர்ந்தவர்கள் பிம்பர் எனப்படுகிறார்கள், தாழ்ந்தவர்கள் பிரதிபிம்பர் எனப்படுகிறார்கள்; எல்லாப் பிம்பங்கள்-பிரதிபிம்பங்களுக்குள் ஹரியே உண்மையான பிம்பம் என்று மகிழ்ச்சியுடன் பாடிக் கண்டு, உண்பது, வைப்பது, கொடுப்பது எல்லாம் தாமரைக்கண்ணனின் திருவடி பூஜைகளே என்று ஆனந்தத்தால் ஆடு.",
        '0.36': "ஆற்றின் நீரை ஆற்றுக்கே அர்ப்பணிப்பது போல, இறைவன் அளித்த தர்மங்களைக் கடலில் துயில்பவனுக்கே அர்ப்பணித்து, வெறும் விதி-தடைகளில் சிக்கிக்கொள்ளாமல் கரண்டி போன்ற கருவியாகச் செயல்பட்டு, எல்லாச் செயல்களிலும் பத்மநாபனை நினைத்துக்கொண்டிரு.",
        '0.37': "அறியாதவர்களும் தாம் அனுபவிக்கும் விஷயங்களை உயர்ந்த ஞானத்துடன் அவனுக்கு அர்ப்பணித்தால் அவன் சித்-சுகம் தந்து திருப்தி செய்கிறான். ஆறுகள், காலம் ஆகியவற்றின் பெருக்கில் ஓட்டத்தைக் கவனிக்காமல் மீண்டும் மீண்டும் நீராடிப் பருகுவதால் சுகம் கிடைப்பது போல இங்கும் நிகழும். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.38': "எந்தச் செயல்களைச் செய்தாலும் கவனத்துடன் ஐயமின்றி தினமும் லக்ஷ்மிநிவாசனுக்கு அர்ப்பணி. பசு புல்லும் நீரும் உண்டு இடைவிடாமல் பால் தருவது போல, மானநிதியான ஹரி அவற்றை ஏற்று பின்னர் இன்பம் அளிக்கிறான்.",
        '0.39': "கிழக்கு, தெற்கு, மேற்கு, வடக்கு திசைகளின் வட்டத்தில் சிவன், அக்னி, வாயு, சந்திரனுக்குள் 'ஹம்ஸன்' என்ற பெயருடைய ஹரி எல்லாக் காலத்திலும் இருக்கிறான்; தேவர்களின் சக்கரவர்த்தியான அவன் தன் விருப்பப்படி பிறருக்குப் புலப்படாமல் 'அவ்யக்தாத்மா' எனப்படுகிறான்.",
        '0.40': "பரிவத்ஸரம், சம்வத்ஸரம் முதலிய ஆண்டுகளில் அநிருத்தன் முதலிய வடிவங்கள் கொண்டு ஹரி குருவாண்டு, சூரிய ஆண்டு, சந்திர ஆண்டுகளாக இருக்கிறான். மகா பராக்கிரமனான ஜகந்நாத விட்டலன் தன்னை நினைப்பவர்களைக் காக்கிறான்; இதையும் ஏற்ற சாதனம், தகுதி ஆகியவற்றையும் அறிந்து (அவ்வாறு வழிபடு).",
      },
    },
    'harikathamrutasara-06': {
      summary: "ஆறாம் சந்தி (பஞ்ச மகா யஜ்ஞம்): வாழ்க்கையே யாகமாகலாம் என்று இச்சந்தி போதிக்கிறது. ஐந்து அக்னிகளில் (தாய், தந்தை, பூமி, நீர், ஆகாயம்; உபநிஷத அக்னி தியானத்தில் மேகம், பூமி, ஆண், பெண்) நாள்களையும் புலன்களையும் தன் செயல்களையும் ஹரிக்கு ஆஹுதியாக்க வேண்டும்; ஒவ்வொரு அக்னியிலும் ஹரி பல வடிவங்களில் (நாராயணனின் முப்பது வடிவங்கள், உடல் உறுப்புகள், பிராணவாயுக்கள், நாள்-பருவங்களில் எண்ணிக்கையுள்ள வடிவங்கள்) உள்ளான். சாமகானப் பகுதிகள், யுகங்கள், வர்ணங்கள், உடல் உறுப்புகள், பூதங்கள், புலன்கள், பத்துப் புலன்களில் தசாவதார வடிவாக ஹரியின் இருப்பைக் காட்டி, எல்லாவற்றையும் கிருஷ்ணனுக்கு அர்ப்பணிப்பதுடன் முடிகிறது.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருத ஸாரத்தைக் கூறுகிறேன்; உயர்ந்த பகவத் பக்தர்களே, இதை மரியாதையுடன் கேளுங்கள். (ஒவ்வொரு சந்தியின் தொடக்கத்திலும் பாடப்படும் பல்லவி.)",
        '0.1': "தாய், தந்தை, பூமி, நீர், ஆகாயம் என்ற ஐந்து அக்னிகளில் நாராயணனின் முப்பது வடிவங்களின் செயல்-வியாப்திகளை நினைத்து, நாள்கள் என்ற சமித்துகளை இடையறாது ஹோமம் செய்து, தூய்மையாக்குவனவற்றுக்கும் தூய்மை தருபவனான பரமனிடம் பரம சுகத்தை வேண்டு.",
        '0.2': "ஆகாயம் என்ற அக்னிக்குச் சூரியக் கதிர்களே புகை, பகலே சுடர், நட்சத்திரங்களே தீப்பொறிகள், சந்திரனே கனல். அதில் இறைவனின் ஐந்து வடிவங்களை நினைத்து, பக்தி ரசம் நிறைந்த சொற்களையே மந்திரமாக்கி அறிஞர்கள் ஹோமம் செய்கிறார்கள்.",
        '0.3': "மழை அக்னிக்குப் பர்ஜன்யனே சமித்து, மேகத் தொகுதிகளே புகை, ஒளிரும் மின்னலே சுடர், இடிமுழக்கமே தீப்பொறி, வஜ்ரமே கனல் என்று கருதி, இவ்வகை அக்னிகளில் அறிந்தவர்கள் தினமும் பரம பக்தியுடன் ஹரிக்கு ஹோமம் செய்கிறார்கள்.",
        '0.4': "பூமியே அக்னி, ஆண்டே சமித்து, ஆகாயமே புகை, இருளே சுடர், திசைகளே கனல், இடைத் திசைகளே தீப்பொறிகள். மழை என்ற ஆஹுதிகளால் ஹரியை மகிழ்வித்து, எல்லாரிடத்திலும் யாகம் செய்பவனாகி எல்லா வடிவமுடையவனை நினைத்துக்கொண்டிரு.",
        '0.5': "ஆண் என்ற அக்னிக்கு வாக்கே சமித்து, புலன்களே சுடர், நாவும் இரு காதுகளும் தீப்பொறிகள், கண்கள் கனல்; நாளும் உண்ணும் உணவு யதுகுல சிரேஷ்டனுக்கு இடும் ஆஹுதிகள்; இவ்வாறு அர்ப்பணித்தால் அவன் தினமும் ஏற்றுக் காக்கிறான்.",
        '0.6': "அவ்வாறே பெண் என்ற அக்னியையும் அறி: இனப்பெருக்க உறுப்பே சமித்து, காமத்தை எழுப்பும் சொற்களே புகை, யோனியே பெருஞ்சுடர், சேர்க்கையே கனல், உற்சாகங்களே தீப்பொறிகள்; வெளிப்படுவது புருஷோத்தமனுக்கு இடும் ஆஹுதி; அவன் ஏற்றுக் காக்கிறான்.",
        '0.7': "இந்த ஐந்து அக்னிகளில் மறக்காமல் ஐந்து வடிவங்கள் கொண்டவனின் இருபத்தைந்து வடிவங்களை தினமும் நினைப்பவர்களுக்கு மீண்டும் பிறவிகளை அவன் அளிக்கமாட்டான். போரில் தன் உறவினரைக் காத்தது போலக் காப்பவன், நிந்தித்தவனுக்கும் நற்கதி அளித்தவன், பயம் போக்கும் தாமரைக்கண்ணன் பக்தவத்சலன்.",
        '0.8': "பஞ்சநாரீ துரகம் போல ஐந்து வடிவங்கள் கொண்ட ஹரி முப்பது வடிவங்களைத் தாங்கி அந்தந்தப் பெயர்களால் அழைக்கப்படுகிறான்; ஐந்து அக்னிகளின் வாய் வழியாக முக்குணமயமான பஞ்சபூத உடலை ஐந்து வகை உயிர்களுக்கு அளித்து அங்கேயே விளையாடுகிறான்.",
        '0.9': "பத்மநாபன், அச்யுதன் முதலிய எண்ணற்ற வடிவங்களில் ஹரி பிரம்மா-சிவன் முதலிய எல்லா உயிர்களின் இதயத்திலும் ஒரே ஆத்மாவாக இருக்கிறான்; அதிபூதம், அத்யாத்மம், அதிதெய்வம் ஆகியவற்றில் 'பிராணன்' என்ற பெயருடன் பத்து வடிவங்களால் பத்து வகைப் பிராணன்களுக்குள் இருக்கிறான்.",
        '0.10': "அறிஞர்கள் நான்கு இடங்களில் அவனது 10,326 வடிவங்களையும், பத்துப் பிராணவாயுக்களில் 18,127 வடிவங்களையும் தினமும் சிந்திக்க வேண்டும்; அங்கே அவன் அந்த வாயுக்களின் பெயர்களால் அழைக்கப்படுகிறான்.",
        '0.11': "அவனது 28,453 நல்ல வடிவங்களையும், மேலும் பதினான்கு வடிவங்களையும் மனத்தில் வைத்துக்கொள்; இவ்வாறு அறிந்து எங்கும் புருஷோத்தமனை வழிபடு, போற்று. (இப்பாடலின் பாடம் முழுமையாகச் சரிபார்க்கப்படவில்லை.)",
        '0.12': "எல்லா உடல்களிலும் ஒலி முதலிய விஷயங்களின் இருப்பிடத்தில் ஹரி 16,416 வடிவங்களால் இருக்கிறான்; வாயு நாகன் முதலிய வடிவங்களால் மூன்றாம் குணத்துக்கு அபிமானி; துர்கா ரமணனான ஹரி புலன்களுக்கு வித்யையையும் தவறான மயக்கத்தையும் அளிக்கிறான்.",
        '0.13': "ஐந்து வகை அவித்யைகளுக்குள், நாகன் முதலிய வாயுக்களின் இருப்பிடத்தில் லக்ஷ்மீநாதன் க்ருத்தன், உல்கன் முதலிய ஐந்து வடிவங்களைத் தாங்கி நல்லோரின் அவித்யையை அறுக்கிறான்; தாமஸர்களுக்கு அஞ்ஞானம் முதலியவற்றை அளித்து அவரவர் சாதனையைச் செய்விக்கிறான்.",
        '0.14': "உத்கீதனாகப் பசுக்களில்; பிரஸ்தாவம், ஹிங்காரம் என்ற இரு வடிவங்களால் ஆடு-செம்மறிகளில்; பிரதிஹாரனாகக் குதிரைகளில்; உயிர் தரும் நிதனனாக மனிதர்களில் ஹரி இருக்கிறான்; இவ்வாறு சாமகானத்தின் ஐந்து பகுதிகள் அவற்றில் உள்ளன. ஒவ்வொரு கணமும் நினைப்பவர்களுக்கு அவன் மீண்டும் பிறவிகளை அளிப்பதில்லை.",
        '0.15': "நான்கு யுகங்களிலும் தானே இருந்து அந்தந்த யுகத்தின் தர்மங்களையும் செயல்களையும் நடத்துவிக்கும் ஹரி வாஸுதேவன் முதலிய நான்கு வடிவங்களை எடுத்து, யுகங்களின் தொடக்கத்தை உண்டாக்குபவனாய் தர்மத்தை நிலைநாட்டுபவனாய்ப் பக்தர்களுக்குச் செல்வம் அளிக்கிறான்.",
        '0.16': "தலையில் நாராயணன், கழுத்திலிருந்து உடலில் வாஸுதேவன், வலப்புறம் ப்ரத்யும்னன், இடப்புறம் அநிருத்தன், கீழ் உறுப்புகளில் ஸங்கர்ஷணன் என்று அறிந்து, எல்லா உடல்களிலும் ஐந்து வடிவனான ஹரியைக் கண்டு மகிழ்.",
        '0.17': "முழு உடலிலும் நாராயணன் இருக்கிறான்; இடுப்பிலிருந்து பாதம் வரை ஸங்கர்ஷணன்; தலையிலிருந்து இடுப்பு வரை வாஸுதேவன்; இடப்புறம் அநிருத்தன்; வலப்புறம் ப்ரத்யும்னன். இவ்வாறு சிந்திப்பவர்களுக்குத் தீட்டு பற்றிய விதி-தடைகள் உண்டா?",
        '0.18': "கைகளில் பத்மநாபன்; வாயில் ஹ்ருஷீகேசன்; மூக்கில் ஸ்ரீதரன்; நாவில் வாமனன்; மென்மையான தோலில் த்ரிவிக்ரமன்; கண்களில் மதுசூதனன்; காதுகளில் கேள்வியாக விஷ்ணு என்ற பெயருடன் ஹரி இருக்கிறான்.",
        '0.19': "மனத்தில் கோவிந்தனும் மாதவனும்; தத்துவங்களில் நாராயணன்; மஹத் தத்துவத்திலும் அவ்யக்தத்திலும் கேசவன். உடலில் இத்தனை வடிவங்களைச் சிந்திக்கும் மகாத்மாக்கள் பூமியில் வெறும் மனிதர்கள் அல்லர்; ஹரியின் கருணை வலிமையால் அவர்கள் தேவர்களுக்குச் சமமானவர்களே.",
        '0.20': "பூமியில் கிருஷ்ண வடிவில்; நீரில் ஹரி என்ற பெயரில்; நெருப்பில் பரசுராமன், உபேந்திரன் என; காற்றில் ஜனார்தனன்; ஆகாயத்தில் அச்யுதன்; மணத்தில் நரஹரி; சுவைகளில் தானே சுவை வடிவாக அதோக்ஷஜன் ஒளிர்கிறான்.",
        '0.21': "உருவத்தில் புருஷோத்தமன்; தொடு உணர்வைத் தரும் அநிருத்தன்; ஒலியில் வியாபித்த ப்ரத்யும்னன்; இனப்பெருக்க உறுப்பில் வாஸுதேவன்; கழிவு உறுப்பில் ஜயாபதி ஸங்கர்ஷணன்; பாதத்தில் நன்கு நிலைநிறுத்துபவனாகத் தாமோதரன் ஒளிர்கிறான்.",
        '0.22': "ஸ்ரீபதி இருபத்துநான்கு தத்துவங்களில் அநிருத்தன் முதலிய வடிவங்களால் வியாபித்திருக்கிறான்; எல்லா உயிர்களின் உடல்களிலும் கொடி போலச் சுற்றிக் கொண்டு பித்ருக்களுக்குத் திருப்தி தருபவனாகி, ஒப்பற்ற மகிமையுடன் தொண்ணூற்றாறு நாமங்களால் நிலைகொண்டிருக்கிறான்.",
        '0.23': "இருபத்துநான்கு தத்துவங்களிலும் அவற்றின் அதிபதிகளான பிரம்மா முதலிய தேவர்களிலும் 1,152 வடிவங்களால் பரவி எல்லா உயிர்களையும் காக்கிறான்; இதில் ஜகத்பதிக்குத் தனக்கென்று எந்தப் பயனும் இல்லை.",
        '0.24': "இந்திராபதி சக்தி முதலிய பதினோரு வடிவங்களால் எல்லாப் புலன்களிலும் 'புருஷன்' என்ற பெயரில் சேர்ந்திருக்கிறான்; அழகிய, நிறை ஞானானந்தமயமான, சித்-வடிவ உடலில் ஒருவனாக, ஒரு கணமும் பிரியாமல் பரம உறவினனாக இருக்கிறான்.",
        '0.25': "பதினாறு வடிவங்களால் ஸ்தூல-லிங்க உடல்களிலும், விஸ்வன், தைஜஸன், ப்ராஜ்ஞன், துர்யன் என்ற (விழிப்பு, கனவு, ஆழ்ந்த உறக்கம், அவற்றுக்கு அப்பாற்பட்ட நான்காம்) நிலைகளிலும் தோன்றுகிறான்; பதினைந்து வடிவங்களைத் தாங்கி பத்துக் கரணங்களிலும், தன்மாத்திரைகளிலும், ஆகாயம்-நெருப்பு-நீர்-பூமியிலும் 'ஆத்மா' என்ற பெயரில் இருக்கிறான்.",
        '0.26': "மனத்திலும் அகங்காரத்திலும் அந்தராத்மாவைச் சிந்தி; அடர்ந்த நற்றத்துவத்தில் (மஹத்தில்) பரமனை; அவ்யக்தத்தில் ஞானாத்மாவை. ஐம்பது எழுத்துகளால் அறியப்படும் அஜன் முதலிய ஐம்பது மூர்த்திகளை எப்போதும் எங்கும் உடல்களில் வழிபடு.",
        '0.27': "இருபத்துநான்கு தத்துவங்களிலும் அவற்றின் அதிபதிகளான பிரம்மா முதலிய தேவர்களிலும் 13,800 வடிவங்களால் பரவி; இருபத்துநான்கு வடிவங்களால் எல்லாரிடத்திலும் பரவிய ஐந்து வடிவனான இறைவன் சாதாரண மனிதனைப் போல மகிழ்கிறான்.",
        '0.28': "கேசவன் முதலிய பன்னிரு நல்ல மூர்த்திகள் பன்னிரண்டு மாதங்களிலும் பன்னிரண்டு திலகங்களிலும் உள்ளனர்; வேதவியாசர், அநிருத்தன் முதலிய வடிவங்கள் ஆறு பருவங்களில் உள்ளன என்று அறிந்து, முப்பது நாள்களிலும் பலனை எதிர்பாராமல் நற்கருமமும் தர்மமும் செய், அவன் கருணையை வேண்டு, போற்று.",
        '0.29': "மண்கட்டி, பொன், இரும்பு, கல், மரம் முதலிய எல்லா ஜடப்பொருள்களிலும் பிரம்மா முதலிய எல்லா உயிர்களிலும் இருந்து, அவர்களுக்குத் தெரியாமலே தினமும் செயல்களைச் செய்விக்கிறான்; எல்லோருக்கும் பிரியனாய் எல்லா விருப்பங்களையும் அளித்து எல்லா உயிர்களையும் காக்கிறான்.",
        '0.30': "ஆண் உடலில் வாஸுதேவ-அநிருத்த வடிவாலும், பெண் உடலில் ஸங்கர்ஷண-ப்ரத்யும்ன வடிவாலும் ஹரி இருக்கிறான். 'த்வா ஸுபர்ணா' சுருதியால் துதிக்கப்பட்ட, எல்லா உயிர்களின் இருப்பிடமான நாராயணனை நல்ல உபாசனை செய்பவர்கள் ஜீவன்முக்தர் எனப்படுவர்.",
        '0.31': "ஹிரண்யகர்ப்பன் முதலானோருக்குள் தன் எண்ணற்ற வடிவங்களால் கருணைக்கடலான ஹரி அவரவரின் எல்லாச் செயல்களையும் தான் துன்பப்படாமல் செய்து செய்வித்து, அவர்களை ஆசிபெற்றோராக்கி, எல்லா தேவர்களின் புண்ணிய கருமத்தை ஏற்றுப் பலன் அளித்துக் காக்கிறான்.",
        '0.32': "கடலில் சேர்ந்த ஆற்று நீர் தன் வேறுபாட்டை அறிய முடியுமா? குமிழிகள் ஆற்று நீரின் நிலையை அறிய முடியுமா? அவ்வாறே பாம்புப் படுக்கையில் துயில்பவனுக்குள் முக்குணத்தால் கட்டுண்ட இவ்வுலகம் இருக்கிறது; ஆகமம் அறிந்தவர் அறிவர், ஞானிகளுக்கு அது தெளிவாகும். (இப்பாடலின் பாடம் ஓரளவே தெளிவு.)",
        '0.33': "புலன்கள், குணங்கள், பூதங்களிலும் அவற்றின் அதிபதிகளான பிரம்மா முதலிய தேவர்களிலும் அவனது நான்கு வடிவங்களை தினமும் எங்கும் நினைத்து, மகிழ்ந்து, ஆடி, தன்வசமிழந்து பாடுபவர்களுக்குத் தன் இருப்பைக் காட்டிப் பிறவியிலிருந்து விடுவித்துப் பேணுகிறான்.",
        '0.34': "மனத்தில் மூல வடிவம்; காதுகளின் இணையில் மத்ஸ்ய-கூர்மர்; தோல்-நாவில் வராஹ-நரசிம்மர்; மூக்கின் குழாயில் சிறுவன் வாமனன்; வாயில் பரசுராமன்; கையில் வாலியை வதைத்த ராமன்; பாதத்தில் ஸ்ரீகிருஷ்ணன்.",
        '0.35': "ஜினர்களை மயக்கும் புத்தன் கழிவு உறுப்பிலும், அசுரர்களை அழிக்கும் கல்கி இனப்பெருக்க உறுப்பிலும் உள்ளனர்; இவ்வாறு பத்துப் புலன்களில் பத்து வடிவங்களை அறிந்து, அனுபவிக்கும் விஷயங்களை 'கிருஷ்ணார்ப்பணம்' என்றால், துன்பம் போக்கும் விஸ்வவியாபகனான ஜகந்நாத விட்டலன் ஏற்கிறான்.",
      },
    },
    'harikathamrutasara-07': {
      summary: "ஏழாம் சந்தி (பஞ்ச தன்மாத்ரம்): ஐம்பூதங்கள் (பூமி, நீர், நெருப்பு, காற்று, ஆகாயம்), அவற்றின் நுண் வடிவங்களான தன்மாத்திரைகள், ஐம்பத்தொரு எழுத்துகள், உடலின் நாடிகள், பிராணன்கள், நாள்கள் ஆகிய அனைத்தும் ஹரியின் இருப்பிடங்கள்; அவற்றில் எண்ணிக்கையுள்ள வடிவங்களால் அவன் இருந்து அவற்றை இயக்குகிறான். இச்சந்தி அவ்வெண்ணிக்கைகளைக் கூறுகிறது; கண்ணாடியில் பொருள் தெரிவது போல நல்லோரின் மனத்தில் அவன் பிரதிபலிக்கிறான் (பிம்ப-பிரதிபிம்பம்) என்கிறது; நரசிம்ம நாம மந்திர ஜபத்தைக் கூறுகிறது; இறைவன் உயிர்களிலிருந்தும் ஜடத்திலிருந்தும் முற்றிலும் வேறுபட்டவன், லக்ஷ்மியும் அவன் குணங்களின் எல்லையைக் காணாதவள், எல்லாம் அவனுக்கு உட்பட்டவை என்று போதித்து முடிகிறது.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருத ஸாரத்தைக் கூறுகிறேன்; உயர்ந்த பகவத் பக்தர்களே, இதை மரியாதையுடன் கேளுங்கள். (ஒவ்வொரு சந்தியின் தொடக்கத்திலும் பாடப்படும் பல்லவி.)",
        '0.1': "பூமி, நீர், நெருப்பு, காற்று, ஆகாயம் என்ற ஐந்து பூதங்களும் அவற்றின் ஐந்து தன்மாத்திரைகளும் உள்ள இவ்வுடலில், ஐம்பத்தொரு எழுத்துகளால் அறியப்படும் ஹரி வியாபித்து, தேவர்களுக்கும் அசுரர்களுக்கும் இடையறாது இன்ப-துன்பங்களை அளித்தபடி விளையாடுகிறான்; வெறுப்பவர்களை வருத்துகிறான்.",
        '0.2': "பிரணவத்தால் உணர்த்தப்படும் அநிருத்தன் மூன்று பெயர்களுடன், உடலின் மூன்று இடங்களில் இருந்து, பதினைந்து, இருபத்தொன்று, இருபத்துநான்கு என எண்ணப்பட்டு, எழுபத்தீராயிரம் வடிவங்களால் நாடிகளை இயக்கி, சூரியனைப் போல உலகில் எங்கும் ஒளிர்கிறான். (இப்பாடலின் பாடம் முழுமையாகச் சரிபார்க்கப்படவில்லை.)",
        '0.3': "உடலின் நான்கு இடங்களில், அவற்றில் ஜீவன், லிங்க (நுண்) உடல், ஸ்தூல உடல் ஆகியவையும் அடங்க, ஹரி விஸ்வன், ஹயக்ரீவன், மூலேசன், அச்யுதன் என்ற ஹம்ச மூர்த்திகள் முதலிய வடிவங்களால் இருக்கிறான். இந்நான்கு இடங்களில் சாந்திவரனை நான்கு வடிவங்களிலும், எங்கும் பத்தொன்பது வடிவங்களிலும் சிந்திக்க வேண்டும்.",
        '0.4': "தூய கண்ணாடியில் எல்லாப் பொருள்களும் பிரதிபலித்துத் தெரிவது போல, பிம்பமான ஹரி ஜட-சேதனங்களுக்குள் இருந்தாலும் நல்லோரின் மனக் கண்ணாடியில் பல வடிவங்களில் ஒளிர்கிறான்; அவன் அசைவற்றவன், நோயற்றவன், மாறாதவன், பிறர் ஆதாரம் தேவையற்றவன், எல்லையற்றவன்.",
        '0.5': "இந்நான்கு உடல்களிலும், கோசங்கள், தாதுக்களிலும் பாரதீபதியான பிராணதேவன் (வாயு) நாளொன்றுக்கு இருபத்தோராயிரத்து அறுநூறு மூச்சுகளின் 'ஹம்ஸ' வடிவில் சூரிய-சந்திர அபிமான தேவதைகளுக்குள் இருக்கிறான்; அவன் கையைப் பற்று (சரணடை); அவன் பிரம்மாண்டம் முழுவதும் நிறைந்திருக்கிறான். (இப்பாடலின் பாடம் முழுமையாகச் சரிபார்க்கப்படவில்லை.)",
        '0.6': "உடலின் நடுவில் வாக்கு-மனம் நிறைந்தவனாக எப்போதும் ஒளிரும் அவன் புலன்கள், தாதுக்கள், எழுபத்தீராயிரம் நாடிகளில் இருந்து, அறியாதவர்க்கு எட்டாத 'பாரத பிரதிபாத்யன்' (மகாபாரதம் கூறும் இறைவன்) எனப்படுகிறான். (தலை, தோள், பாதங்களின் எண்ணிக்கையைக் கூறும் முதல் வரி தெளிவற்றது.)",
        '0.7': "ரிக்வேதத்தில் துதிக்கப்பட்ட லக்ஷ்மீரமணன் விஷ்ணு என்ற வடிவில், உடலின் அலைகளிலும் (பசி, தாகம் முதலியன) பூதங்களிலும் வடிவம் கொண்டு, அறுபத்துநான்கு கலைகளைத் தாங்கி, பிரம்மா-சிவன் முதலிய முதன்மையானவர்களுக்குள் இருந்து 'சதுஷ்பாத்' என்ற பெயரால் உலகில் இடையறாது விளையாடுகிறான்.",
        '0.8': "புல் முதல் பிரம்மா வரை உயிர்களின் நான்கு உடல்களில் நாராயணனின் 1,526 வடிவங்களை அறிஞர்கள் எண்ண வேண்டும்; சூரியன், ஆதித்யன் முதலிய நாமங்களை தினமும் ஜபிப்பவர்களுக்கு அவன் ஆரோக்கியமும் செல்வமும் அளிக்கிறான்.",
        '0.9': "ஆதிபௌதிகத்தில் 574 வடிவங்களும், அத்யாத்மத்தில் 1,021 வடிவங்களும், அதிதெய்வத்தில் 231 மூர்த்திகளும் அறிந்து அறிஞர்கள் தியானிக்க வேண்டும். (இப்பாடலின் பாடம் முழுமையாகச் சரிபார்க்கப்படவில்லை.)",
        '0.10': "அழகிய இரவை உண்டாக்குபவன் (சந்திரன்) எனப்பட்டு ஸங்கர்ஷண-ப்ரத்யும்னர் சந்திர-சூரியருக்குள் 360 வடிவங்களால் இருக்கிறார்கள்; அவன் 'அஹஸ்-ஸம்வத்ஸரன்' என்ற சிறப்புப் பெயரால் அழைக்கப்படுகிறான்; இதை அறிந்தவர்களுக்கு ஆனந்தமயனான அவன் ஆரோக்கியமும் நற்பேறும் அளிக்கிறான்.",
        '0.11': "ஐம்பத்தொரு எழுத்துகளில் உறையும் ரமாபதி எல்லாருக்குள்ளும் வியாகிருத ஆகாயம் வரை வியாபித்து, வேதங்கள், இலக்கணம், மகாபாரதம் முதலிய பல சாஸ்திர-புராண-பாஷ்ய தொகுப்புகளை இயற்றி மனோ-வாங்மயன் எனப்படுகிறான். (இப்பாடலின் பாடம் முழுமையாகச் சரிபார்க்கப்படவில்லை.)",
        '0.12': "பாரப்ருத் என்ற பெயருடையவனின் 1,624 மூர்த்திகள் சராசரங்களில் எங்கும் நிறைந்துள்ளன; இருபத்துநான்கு ஜடத் தத்துவங்களிலும் பதினாறு சேதனங்களிலும் எல்லா இடங்களிலும் அவன் தன் வடிவைக் காட்டுகிறான்.",
        '0.13': "மணிமுடியின் மேல் மணி போல பிரம்மா முதலியோரின் மனத்தில் ஒளிரும் அவன் பிரம்மாண்டத்திற்கு ஆதாரமும் ஆதேயமுமாக இருக்கிறான்; சந்திரனில் 242 வடிவங்களாலும், சந்திரனின் முயல் களங்கத்தில் 142 வடிவங்களாலும் விடாமல் இருக்கிறான்.",
        '0.14': "எல்லாப் பொருள்களிலும் அவனது 2,008 வடிவங்களை அறிந்து ஸ்ரீவரனை வழிபடு, வரங்கள் கேள், போற்று. வெறுமனே நீரில் மூழ்கி வெயிலில் விரல் எண்ணினால் என்ன பயன்? நல்ல குருமார்களையும் பெரியோர்களையும் பின்பற்றாதவன் மர்மத்தை அறியமாட்டான்.",
        '0.15': "மீண்டும் சித்-வடிவ உடலுக்குள் ஹரி நரசிம்ம வடிவில் ஏறத்தாழ 80,725 வடிவங்களால் உயிர்களுக்காக இருக்கிறான்; பகல்-இரவைக் கொண்டுவரும் மரணத்துக்கும் தானே மரணமாகி, சேவகரிடம் அன்புடையவன், பயத்தை அழிப்பவன், நற்பேறு நிறைந்தவன்.",
        '0.16': "பிரம்மாவில் இருபத்தேழு, சிவனில் இருபத்தெட்டு வடிவங்களால் உள்ள 'ஜ்வரஹர' என்ற பெயருடைய நரசிம்மனின் வடிவங்கள் 2,827 என எண்ணப்படுகின்றன. அவனை நினைத்த மாத்திரத்தில் சூரிய பிம்பத்தைக் கண்ட பனி போல பாவக் குவியல்கள் மறைகின்றன.",
        '0.17': "ஒரு மாதம் இடைவிடாமல், உறுதியான ஆசனத்தில் ஒருமுகப்பட்ட மனத்துடன் கபடமின்றி நரகேசரியின் மங்கல நாம மந்திரத்தை சலிப்பின்றி ஜபித்தால் அவன் பாவங்களை அழித்து விருப்பங்களை நிறைவேற்றி இறுதியில் பரம கதியை அளிக்கிறான்.",
        '0.18': "நான்கு மூர்த்தி ஹரி பிரம்மாவில் முப்பது வடிவங்களால், வாயுவில் ப்ரத்யும்னனாக இருபத்தேழு வடிவங்களால், பிரம்மாவின் புதல்வர்களில் இருபத்தைந்து, பதினெட்டு வடிவங்களால் இருக்கிறான்; இவற்றை அறிந்து நூறு ஆண்டு வாழ்க்கையில் சதுராத்மகனின் திருவடிகளை வழிபட்டுக்கொண்டிரு.",
        '0.19': "நூறு ஆண்டுகளுக்கு முப்பத்தாறாயிரம் நாள்கள்; ஆண்-பெண் பேதமின்றி உடலில் நாடிகளும் அவ்வளவே உள்ளன. ஹரியின் எழுபத்தீராயிரம் வடிவங்களை நினைத்து, அனைத்துக்கும் ஆதாரமானவனை நிறைவானவன் என அறிந்து எங்கும் வழிபடு.",
        '0.20': "காலம், கர்மம், குணம், இயல்பு ஆகியவற்றின் இருப்பிடமான லக்ஷ்மிப்ரியன் அந்தந்த வடிவ-பெயர்களால் அழைக்கப்பட்டபடி உள்ளிருந்து, விளையாட்டாக எல்லா உயிர்களையும் காக்கிறான், அழிக்கிறான், படைக்கிறான்; மூலகாரணமான பிரகிருதியையும் அதன் குணங்களையும் காரியங்களையும் தன் இருப்பிடமாகக் கொள்கிறான்.",
        '0.21': "எண்ணெய்-திரிகளைச் சார்ந்து விளக்குகள் எரிந்து வீட்டின் இருளைப் போக்கி உள்ளிருக்கும் பொருள்களைக் காட்டுவது போல, தாமரைக்கண்ணன் தன்னவர்களின் பக்தி, ஞானம், கர்மத்தில் மகிழ்ந்து அவர்கள் மனத்தில் ஒளிர்ந்து தன் குணம், உருவம், செயல்களைக் காட்டுகிறான்.",
        '0.22': "எந்த உடலை அளித்தாலும், எந்த உலகில் வைத்தாலும், எந்த இடத்தில் இருந்தாலும், எந்த நிலைகள் வந்தாலும், இவ்வாறு ஜட-சேதனங்களில் பராவரேசனின் உருவம்-குணங்களை எண்ணியபடி நல்லறிவுடனும் பக்தியுடனும் அவன் அருளை வேண்டு, போற்று.",
        '0.23': "ஒவ்வொன்றிலும் மற்றவை கலந்துள்ளன; இவ்வாறு மனத்தில் எண்ணிய இந்திரேசனின் வடிவங்களைப் பற்றி ஊகத்துக்கு இடமே இல்லை. கடலில் தோய்த்த துணியின் ஒவ்வொரு இழையிலும் நீர்த்துளி பரவுவது போல அவன் சராசரங்களில் வியாபித்திருக்கிறான்.",
        '0.24': "அவனது ஒரு வடிவத்தில், ஒரு அங்கத்தில், ஒரு ரோமத்தில், ஒரு இடத்தில் எண்ணற்ற கோடி பிரம்மாண்டங்கள் அடங்கியுள்ளன. முன்பு மார்க்கண்டேயர் இந்திரேசனின் ஒரே வடிவத்தில் படைப்பையும் ஊழியையும் காணவில்லையா? அளவிட முடியாதவனிடம் வியப்பென்ன?",
        '0.25': "அவனது ஒரு எல்லையற்ற வடிவத்தில் பல வடிவங்கள் உள்ளன; ஒரே வடிவில் உலகங்கள் உள்ளன; ஒரே நேரத்தில் படைப்பு, காப்பு முதலிய செயல்களை யாருக்கும் தெரிவிக்காமல் செய்து உலகில் வியாபித்திருக்கிறான். நந்தநந்தனன் போர்க்களத்தில் இந்திரனின் மகனுக்கு இதைக் காட்டவில்லையா?",
        '0.26': "'நவநாரீ குஞ்சரம்' (ஒன்பது பெண்களால் அமைந்த யானை உருவம்) ஒரே வடிவமாகத் தோன்றி ஒவ்வொரு உறுப்பிலும் வேறுபட்டிருப்பது போல, ஸ்ரீரமேசனின் மூர்த்திகள் ஒரே வடிவிலும் உறுப்புக்கு உறுப்பு வேறுபட்டும் தோன்றுகின்றன; பிரம்மாண்டத்தில் அவன் மாறுபாடற்ற விராட் எனப்படுகிறான்.",
        '0.27': "பிரம்மாண்டத்தில் லக்ஷ்மி நரசிம்மனின் உருவ-குணங்கள் கடலலைகள் போலத் திரண்டுள்ளன: காரணப் பகுதிகளின் ஆவேசமும் வியாப்தியும், வெளிப்பட்ட-வெளிப்படாத காரியங்கள்; இருபத்துநான்கு விபூதி வடிவங்களும் அந்தர்யாமியின் வடிவங்களே.",
        '0.28': "மணிகளின் மாலையிலுள்ள நூல் போல பிரணவத்தால் உணர்த்தப்படுபவன் சேதன-அசேதன உலகில் தினமும் இன்பம் நிறைந்தவனாய் விளையாடுகிறான்; அவனுக்குக் களைப்பில்லை; கருணைக்கடலான அவன் எண்ணற்ற உயிர்த் தொகுதியில் ஓர் அம்ச வடிவில் நின்று இயக்குகிறான்.",
        '0.29': "ஜீவ-ஜீவ, ஜட-ஜட, ஜீவ-ஜட, ஜட-ஜீவ பேதங்கள் உள்ளன; ஸ்ரீவரனான ஹரி இவை எல்லாவற்றிலிருந்தும் முற்றிலும் வேறுபட்டவன், தனிச்சிறப்பானவன் (பஞ்சபேதம்). லக்ஷ்மியும் பிரம்மாண்டத்தில் இம்மூவரிலிருந்தும் வேறுபட்டவள்; அவள் எல்லைக்குட்பட்டவளாயினும் ஒப்பற்றவள் என அறிந்து இவ்விருவரையும் பணி.",
        '0.30': "தேவர்கள் அவன் குணங்களை அறியார்; வேத அபிமானிகள் எனப்படும் வாணி முதலியோர் கூற வல்லவர்கள் எனினும் குணத்தொகுதியை அறியார்; பிரம்மாவும் அறியாத ஆழ்ந்த குணங்களை லக்ஷ்மி ஒருத்தியே அறிவாள். ஸ்ரீதரன் ஒருவனே உபாசிக்கத் தக்கவன், நற்குணம் நிறைந்த ஹரி என்று அறி.",
        '0.31': "அவனது எண்ணற்ற குணங்களின் எல்லையைக் காணாமல் மகாலக்ஷ்மி இறைவனுக்கு அணிகலன்களாக, ஆயுதங்களாக, ஆடைகளாக, வசிப்பிடங்களாக ஆகி, அவனது எல்லையற்ற மகிமையை மனத்தில் நிறுத்தி, இடைவிடாமல் அவன் தூதுப்பணி செய்தபடி அவன் அதீனத்தை அடைந்துள்ளாள்.",
        '0.32': "பிரளயக் கடலில் உள்ள படகு கரை காணாமல் சுற்றுவது போல, தாமரைக்கண்ணனின் தூய குணங்களையும் உருவங்களையும் சிந்தித்தபடி மகாலக்ஷ்மி ஆதாரம் காணாமல் அலைகிறாள்; அப்படியிருக்க சிறிய உயிர்களுக்கு மூவுலகிலும் அவன் மகிமைகள் எப்படிக் கைகூடும்?",
        '0.33': "ஸ்ரீநிகேதனன், சாத்வதர்களின் தலைவன், ஞானத்தால் அடையத்தக்கவன், கயாசுரனை அழித்தவன், முனிவர் குலங்களால் மதிக்கப்படுபவன், மானம் அளிப்பவன், மாமனை (கம்சனை) அழித்தவன், எளியவர்க்குக் கற்பக மரம், மதுவைப் பகைத்தவன், உயிர் அளிப்பவனான ஜகந்நாத விட்டலனே கதி என்று தினமும் நம்பியவர்களைக் காக்கிறான்.",
      },
    },
    'harikathamrutasara-08': {
      summary: "எட்டாம் சந்தி (மாத்ருகா): பாதங்களிலிருந்து தலை வரை உடல் உறுப்புகள், தாமரை நிலையங்கள், நாடிகள், புலன்கள், பிராணன்கள், அவற்றின் அபிமான தேவதைகளைக் குறிப்பிட்டு, அவற்றுக்குள் ஹரி இயக்குபவனாக எண்ணிக்கையுள்ள வடிவங்களில் இருப்பதை இச்சந்தி காட்டுகிறது. விழிப்பு, கனவு, ஆழ்ந்த உறக்கம் என்ற மூன்று நிலைகளை விஸ்வன், தைஜஸன், ப்ராஜ்ஞன் வடிவங்களுடன் விளக்குகிறது; சாமகானத்தின் ஐந்து பகுதிகளை இறைவனின் ஆயுதங்களில் வைக்கிறது; லக்ஷ்மியும் அவன் குணங்களின் எல்லையைக் காணாதவள் என்கிறது; செல்வம், உடல், வீடு, குடும்பத்தில் ஹரியைக் கண்டு 'நான் அவன் சேவகன்' என எண்ணவேண்டும் என்ற உபதேசத்துடன் முடிகிறது.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருத ஸாரத்தைக் கூறுகிறேன்; உயர்ந்த பகவத் பக்தர்களே, இதை மரியாதையுடன் கேளுங்கள். (ஒவ்வொரு சந்தியின் தொடக்கத்திலும் பாடப்படும் பல்லவி.)",
        '0.1': "வலப் பாதத்தில் ஜயந்தனுக்குள் சுமேதன் என்ற ஹரி இருக்கிறான்; பெருவிரலில் வாயு பாரப்ருத் வடிவில் இருக்கிறான்; மூட்டுகளில் டங்கி, தாரா முதலிய பெயர்கள் கொண்ட ஐந்து வடிவங்களால் காத்து, இடைவிடாமல் தான் நடந்து உடலை நடத்துகிறான். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.2': "கைகளின் மூட்டுகளில் கபிலர், சார்வாங்கர் முதலிய வடிவங்களால் தினமும் அளவற்ற செயல்களைச் செய்கிறான்; எளியவர்களிடம் அன்புடைய அவன் பக்கத்திலும், குதம்-இனப்பெருக்க உறுப்புகளிலும் இருந்து வலிமையான வடிவங்களால் வயிற்றுக்குள் உறைகிறான். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.3': "நாபி மூலத்தில் ஆறு இதழ்கள் உடைய ஐந்து தாமரைகள் உள்ளன; அவற்றில் அநிருத்தன் முதலிய பெயர்கள் கொண்ட ஐந்து மூர்த்திகள் உள்ளன; அவை அநாதியான கர்மம், இயல்பு, குணங்களுக்கேற்ப உயிர்களுக்குக் கருவை அளித்து, வழி தவறாமல் செயல்களைச் செய்கின்றன.",
        '0.4': "நாபியிலுள்ள ஆறு மூலை மண்டலத்தில், வருங்கால பிரம்மாவுக்குள் முத்துப் பிரகாசமுடைய ஸ்ரீப்ரத்யும்னன் தேவகணங்களால் சேவிக்கப்பட்டு இருக்கிறான்; கௌஸ்துபம் முதலிய அணிகலன்களாலும் ஆயுதங்களாலும் ஒளிர்ந்து மிகக் கொடிய பாவ புருஷனை நாளும் வற்றச் செய்கிறான்.",
        '0.5': "வயிற்றின் நடுவில், சுஷும்னையில், பன்னிரு சூரியர்களின் மண்டலம் உள்ளது; அங்கே ஐந்து வடிவனான ஹரி 360 வடிவங்களால் பகல்-இரவுகளின் அபிமான தேவதைகளைக் காத்து நாளும் தைத்தியர்களை அழிக்கிறான்.",
        '0.6': "இதயத்தில் எட்டு இதழ் தாமரை உள்ளது; அதனுள் 'ப்ராதேசன்' (சாண் அளவினன்) என்ற பெயருள்ள பிம்ப வடிவான ஹரி உதித்த சூரியனைப் போலத் தோன்றுகிறான்; பத்மம், சக்கரம், சங்கு, கதை, தோள்வளை, கங்கணம், மகுடம், மோதிரம், பதக்கம், கௌஸ்துபம், ஹாரம், கழுத்தணி முதலியவற்றால் அலங்கரிக்கப்பட்டிருக்கிறான்.",
        '0.7': "கழுத்தில் இரண்டு இதழ் தாமரை ஒளிர்கிறது; அங்கே முக்கியப் பிராணன் தன் துணைவியுடன் ஹம்ஸோபாசனை (மூச்சு ஜபம்) செய்கிறான்; நீர், உணவு முதலியவற்றுக்கு இடம் தருபவனாய் உதானன் என்ற ஹரி எல்லா உயிர்களுக்குள்ளும் பேசிப் பேசச் செய்கிறான். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.8': "மூக்கில் அஸ்வினி தேவர்கள், மூச்சின் அபிமானி பிராணன், பாரதி, ஹம்ஸன், தன்வந்திரி முதலியோர் உள்ளனர்; சந்திரனும் சூரியனும் கண்ணிணையின் அதிபதிகள்; அவர்களுக்குள் லக்ஷ்மீசன் ததி-வாமன வடிவில் இயக்குகிறான். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.9': "வலக் கண்ணில் தூண் வடிவில் ப்ரத்யும்னன் அவனது உருவ-குணங்களைத் தாங்கிய லக்ஷ்மியுடன் இருக்கிறான்; வாயு, சிவன் முதலிய எல்லா தேவர்களாலும் சேவிக்கப்பட்டு எல்லாப் பொருள்களையும் காட்டுகிறான். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.10': "கண்களில் வசிஷ்டர், விஸ்வாமித்திரர், பரத்வாஜர், கௌதமர், அத்ரி, ஜமதக்னி என்ற பெயருடையோரும், இந்திரன், சூரியன், தரித்ரி, பர்ஜன்யன் முதலிய தேவர்களும் இருந்து, மூவுலக நாயகனை நாளும் பரம பக்தியுடன் வழிபடுகிறார்கள்.",
        '0.11': "கண்ணின் ஒளியில் கபிலர், இந்திரன் முதலிய திக்பாலர்களுடன், வலக் கண்ணின் முகத்தில் விழிப்பு நிலையின் விஸ்வன் என்ற வெண்ணிற நான்கு கை உடையவன் இருந்து, அன்புடன் உயிர்களுக்குப் புற விஷயங்களை உண்ணச் செய்து விழிப்பு நிலையை அளிக்கிறான். (பாடலின் இறுதிப் பெயரடை தெளிவற்றது.)",
        '0.12': "திசை தெய்வங்கள் இருபுறமும் நிலைத்துள்ளனர்; காதுகளில் தீர்த்தங்களின் அபிமான தேவதைகள், முக்கியமாக தேவ நதி (கங்கை) உள்ளனர்; வலக் காதில் கங்கைக்கு மூலமான த்ரிவிக்ரமன் இவ்வாறு சிந்திப்பவர்களைத் தூய்மையாக்குகிறான். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.13': "மனத்தில் காமனும் இந்திரனும்; அகங்காரத்தில் சிவன்; சித்த-சேதனங்களின் அபிமானிகளான கருடன்-சேஷனுக்குள் எப்போதும் நிலைத்த பத்தொன்பது முகங்கள் கொண்ட தைஜஸன் உயிர்களுக்குக் கனவு நிலையை அளித்து 'ப்ரவிவிக்தபுக்' (நுண்ணிய விஷயங்களை அனுபவிப்பவன்) எனப்படுகிறான்.",
        '0.14': "ஞானமயனான தைஜஸன் இதய இடத்தை அடைந்து 'ப்ராஜ்ஞன்' என்ற பெயருடன் சித்-சுகத்தின் வெளிப்பாட்டை அளித்து, வணங்குவோருக்கு விருப்பத்தை நல்குகிறான்; உணர்வின்றி ஆழ்ந்த உறக்கத்தை வரச் செய்து, மீண்டும் தானே உயிர்களுக்குக் கனவு-விழிப்பு நிலைகளை அளிக்கிறான்.",
        '0.15': "நாவில் வருணனும் மத்ஸ்ய வடிவ ஹரியும், உபேந்திரனும், இந்திரனும்; அண்ணத்தில் பர்ஜன்யனும் சூரியனும்; கண்ணில் வாமனன்; நெற்றியில் சிவனும் கேசவனும்; கன்னத்தில் ரதியின் நாதனான காமனும் அவனுக்குள் ப்ரத்யும்னனும். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.16': "ரோமங்களில் வசந்தன்; வாயில் அக்னி, பார்கவன், தாமரையில் பிறந்த பிரம்மா; தலையில் மூன்று சிகர வாசஸ்தலனான வாஸுதேவன்; மனத்தில் விஷ்ணு; குடுமியில் மகேஸ்வரனும் நரசிம்மனும் உள்ளனர்; அந்த ஸ்வாமி தினமும் தன்னை நினைப்பவர்களின் அகால மரணத்தை நீக்குகிறான். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.17': "மகுடத்தில் வாஸுதேவன் பதினாறு வடிவங்களைத் தாங்கி, முகம், கண்கள், காதுகள் முதலிய உறுப்புகளில் தானே ஆட்சியாளனாகி, எப்போதும் விளையாட்டாக இன்பமயனாய்க் கேட்டுக் கேட்கச் செய்து, பார்த்துப் பார்க்கச் செய்து, பேசிப் பேசச் செய்கிறான்.",
        '0.18': "எழுபத்தீராயிரம் நாடிகளில் முக்கியமானவை நூற்றொன்று; அவற்றில் ஹரியின் நூற்றொரு மூர்த்திகள் உள்ளன. இவற்றை உடலின் 'கலசம்' என்ற பெயருடைய ஹரியின் கலைகள் என அறிந்து அந்தணர்கள் இடைவிடாமல் பேரன்புடன் வழிபடுகிறார்கள். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.19': "இதற்குக் காரணம், பன்னிரண்டு நாடிகளிலும் புலன்களிலும் கங்கை முதலிய தூய தீர்த்தங்கள் உள்ளன; அங்கே பத்மநாபன் கேசவன் முதலிய பன்னிரு வடிவங்களால் இருக்கிறான்; மென்மையான சுஷும்னையில் ஒரே ஆத்மாவாகக் கூறப்படுகிறான்.",
        '0.20': "வேதங்கள் கூறும் ஸ்ரீப்ரத்யும்ன தேவன் உடலில் சுஷும்னை, இடை, பிங்கலை நாடிகளில் விஸ்வன் முதலிய வடிவங்களால் இருக்கிறான்; தூய ஆத்மாவான அவன் வாணி, வாயு, நான்முகன் ஆகியோருக்குள் இருந்து எல்லா உயிர்களின் கர்ம-குணங்களுக்கேற்ப நடத்துகிறான்; எங்கும் பரந்தவன்.",
        '0.21': "ஆண்டு, அயனம், பருவம், மாதம், பக்ஷம் என்ற பெயர்களால் அழைக்கப்பட்டபடி, நீல மேக வண்ணனான அநிருத்தன் அநிருத்தன் முதலிய ஐந்து வடிவங்களால் எங்கும் பரவியுள்ளான்; கருணைக்கடல் நாற்பத்தைந்து வடிவங்களால் இத்தகைய பக்தர்களுக்குக் கிடைக்கிறான். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.22': "ஐந்து வடிவனான ஹரிக்கு இருபத்தைந்து வடிவங்கள் உள்ளன; பாடல் அவற்றை ஐந்து திதிகளாலும் இருபத்துநான்கு (தத்துவங்களாலும்) பெருக்கிக் கூறுகிறது (கணக்கு தெளிவற்றது). மனம் அவனை அடைந்தவனுக்கு முத்தாபங்களின் பெருங்குற்றங்கள் எங்கே?",
        '0.23': "நாள், யாமம், முகூர்த்தம், நாழிகை முதலிய பிரிவுகளில் இருந்து, கங்கைப் பெருக்கு போல 'காலம்' என்ற பெயரில் ஓடுகிறான்; பார்கவி (லக்ஷ்மி) அவனது குணம்-உருவம்-செயல்களின் வெள்ளத்தில் மூழ்கி எப்போதும் ஆனந்தமயமாக இருக்கிறாள்.",
        '0.24': "வேதங்களின் அபிமான தேவியான லக்ஷ்மி தராதரனின் குணம்-உருவம்-செயல்களின் தொடக்கம், நடு, முடிவை மனத்தில் எண்ணினாலும் காணமாட்டாள்; ஆயினும் கருணைக்கடலான உலக நாயகன் பிச்சைக்காரன் விருந்தழைப்பை ஏற்பது போல அவளை மனைவியாக ஏற்றான். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.25': "ஸ்ரீதேவியிடமுள்ள எல்லா நற்குணங்களும் புல் முதல் உயிர்கள் வரை வரிசைக்கேற்பக் குறைந்த அளவில் உள்ளன என்று அறிந்தவர்கள் பக்தியுடன் சிந்திக்க வேண்டும். அவள் தேவதேவனின் மனைவி, பிரம்மாவின் தாய்; ஆயினும் அவனை ஒருபோதும் முழுமையாக அறியமாட்டாள்; அப்படியிருக்க சாதாரண மனிதர்களைப் பற்றிச் சொல்வதென்ன? (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.26': "பால், தயிர், வெண்ணெய், நெய்யில் சாந்தி ரமணன் 'சௌரபன்' என்ற பெயராலும், ஞான-கிரியா-இச்சா சக்திகள் என்ற நான்கு பெயர்களாலும் அழைக்கப்படுகிறான்; பாரதி, வாக்தேவி, வாயு, பிரம்மா அங்கே எப்போதும் நிலைத்திருக்கிறார்கள். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.27': "எட்டு வசுக்கள், ஒன்பது பிரஜாபதிகள், நாற்பத்தொன்பது மருத்கணங்கள், பதினொரு ஆதித்யர், அவ்வளவு ருத்திரர், இரு அஸ்வினிகள்; நூற்றில் பத்து குறைந்த (தொண்ணூறு) இத்தேவர்களை பிரம்மா, வாயு, கருடன், சேஷனுக்குள் இருந்து நான்கு மூர்த்தி ஹரி இயக்குகிறான்.",
        '0.28': "சக்கரத்தில் ஹிங்காரனாக, சங்கில் பிரதிஹாரனாக, கதையில் நிதனனாக, தாமரையில் பிரஸ்தாவனாக, கருணையுள்ளவன் உத்கீதன் என்ற பெயரில் (இவை சாமகானத்தின் ஐந்து பகுதிகள்) தோன்றுகிறான்; சங்கு, சக்கரம் முதலிய ஆயுதங்களில் ரமாரமணனின் இவ்வைந்து வடிவங்களை நினைத்துத் தாங்கிக்கொள்.",
        '0.29': "உடலே தேர்; வாக்கின் அபிமான தேவி அதன் கயிறு எனப்படுகிறாள்; காதில் ரோஹிணி, சந்திரன், வருணன் குதிரைகள் எனப்படுகிறார்கள்; பிரணவத்தால் உணர்த்தப்படும், பிராணன் என்ற பெயருடையவன் தேர்த்தலைவன் எனப்படுகிறான். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.30': "அவனது அளவற்ற மகிமையும் எல்லையற்ற குணங்களும் வரையறுக்கப்பட்ட எழுத்துகளாலான சுருதி-ஸ்மிருதிகளுக்கு எட்டாதவை; அவற்றின் அபிமானிகளான பிரம்மா, சிவன், இந்திரன் முதலிய தேவர்களும் தினமும் அறிய முடியாது; தன் மகிமையின் தொடக்கம், நடு, முடிவை எல்லாம் அறிந்த அவனே அறிவான்.",
        '0.31': "செல்வம், உடல், வீடு, மனைவி, மக்கள், நண்பர் முதலியவற்றில் ஹரி பிரத்யகாத்மாவாக நிலைத்திருக்கிறான் என்று அறி; இவ்வாறு அறிந்து உயர்ந்தோர், தாழ்ந்தோர், நடுத்தரத்தோர் அனைவருக்கும் நாளும் திருப்தி அளித்து, கடமை முடித்தவனாய், மயங்காமல் 'நான் அவன் சேவகன்' என்று எண்ணு.",
        '0.32': "தேவதேவேசனின் அழகிய வடிவங்களை எல்லா உடல்களிலும் விடாமல் இடைவிடாது சிந்தித்து, வழிபட்டு, கண்டு மகிழ்ந்திரு; ஸ்ரீவரனான ஜகந்நாத விட்டலன், வீழ்ந்தவர் கூட்டத்தைத் தூய்மையாக்குபவன், மனமகிழ்ந்து கருணையுடன் பிறவித் துயரைப் போக்குகிறான்.",
      },
    },
    'harikathamrutasara-09': {
      summary: "ஒன்பதாம் சந்தி (வர்ணப் பிரக்ரியை, உதாத்த-அனுதாத்த): ஐம்பத்தொரு எழுத்துகளாலும், உதாத்த-அனுதாத்தம் முதலிய வேத ஸ்வரங்களாலும், சந்தி-விசர்கம்-பிந்து ஆகியவற்றாலும் குறிக்கப்படுபவன் ஹரியே; அவற்றிலுள்ள அவனது பெயர்-உருவங்களை அறிந்து உபாசிப்பவர்கள் பேசுவதே வேதப் பொருள். உடல்-இடம்-காலம் சார்ந்த செயல்களை ஆசையின்றிச் செய்து அவனுக்கு அர்ப்பணிக்க வேண்டும்; ஜீவன் அணு அளவினன், இறைவன் அவனுடன் இதயத் தாமரையில் இருக்கிறான்; அந்தந்த தெய்வங்களின் இடத்தில் அந்தந்த மனநிலைகள் தோன்றுகின்றன; நுண் நாடிகள், தாதுக்கள் விவரிக்கப்படுகின்றன; உடலில் இறைவனின் வடிவங்களை நினைக்கும் பக்தன் அபரோக்ஷ ஞானியாகிறான் என்று இச்சந்தி கூறுகிறது.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருத ஸாரத்தைக் கூறுகிறேன்; உயர்ந்த பகவத் பக்தர்களே, இதை மரியாதையுடன் கேளுங்கள். (ஒவ்வொரு சந்தியின் தொடக்கத்திலும் பாடப்படும் பல்லவி.)",
        '0.1': "ஐம்பத்தொரு எழுத்துகளாலும், உதாத்த, அனுதாத்த, பிரசய, ஸ்வரித ஸ்வரங்களாலும், சந்தி, விசர்கம், பிந்துவாலும் குறிக்கப்படுபவன் ஹரியே. அவற்றிலுள்ள அவனது பெயர்-உருவங்களை அறிந்து உபாசிப்போர் பூமியில் தேவர்களுக்குச் சமமானவர், மனிதர் அல்லர்; அவர்கள் பேசுவதே வேதப் பொருள். (பிரசயம்: சமமான ஒரே சுர ஸ்வரம்.)",
        '0.2': "ஈசனிடம் ஞானம், பகவத் தாசர்களிடம் நற்பக்தி, விஷயங்களில் ஆசையின்மை, மித்யாவாதியிடம் நாளும் வெறுப்பு (கவியின் மாத்வ நோக்கில் மித்யாவாதி என்பவன் உலகம் பொய் என்று போதிப்பவன்). இந்த எல்லா உயிர்களிலும் ரமேசன் இருக்கிறான் என்று அறிந்து அவர்களின் விருப்பங்களை நிறைவேற்றுவதே மகா யாகம், ஹரி பூஜை.",
        '0.3': "முப்பது தேவர்களுக்கு ஒரே ஆத்மா எனப்பட்டு, பூமி, நீர், நெருப்பிலும், பத்துப் புலன்களிலும் அவற்றின் அதிபதிகளான பிராணன் (வாயு), ஆதித்யர்களிலும் நிலைத்து, எப்போதும் அறியப்பட்டவனாய், எல்லையற்ற மகிமை உடைய, நிதனன் என்ற பெயருடைய ஸங்கர்ஷணன் எல்லா விஷயங்களையும் ஏற்கிறான்.",
        '0.4': "உடல், இடம், காலம் சார்ந்த மூன்று வகை செயல்கள் உள்ளன; அவற்றில் விதிக்கப்பட்டவற்றை அறிந்து ஆசையின்றிச் செய்து, ப்ருஹதி என்ற பெயருடைய பாரதீசனின் (வாயுவின்) மகிமையுள்ள வடிவை மனத்தில் நினைத்து, தினமும் பரம பக்தியுடன் இறைவனுக்கு அர்ப்பணி.",
        '0.5': "மூன்று வகைச் செயல்களில் கம்சாரி, பார்கவன், ஹயவதனன் வடிவங்களால் தூண்டுபவனாய் ஒன்பது வடிவங்களைத் தாங்கி, தான் மாறாதவனாய் அறிஞர், மனிதர், அசுரர் மூலம் செயல்களைச் செய்து செய்வித்து, சார போக்தாவாய் ஏற்றுப் பிறருக்கு அளிக்கிறான்.",
        '0.6': "நெருப்பில் சமைத்த உணவை நெருப்பிலேயே ஹோமம் செய்வது போல, தேவேசன் எல்லாச் செயல்களையும் தானே செய்து செய்விக்கிறான்; இதை அறிந்து மனம்-வாக்கு-உடலால் தினமும் ஐயமின்றி அர்ப்பணி; துயர் போக்கும் அவன் தன்னவர் அர்ப்பணத்தை எப்போதும் ஏற்றுத் திருப்தி செய்கிறான்.",
        '0.7': "குதிரை வாலின் நுனி முடியை நூறு பங்காக்கி, அதில் ஒரு பங்கை மீண்டும் நூறு பங்காக்கினால் எவ்வளவு நுண்ணியதோ அவ்வளவு நுண்ணியது ஜீவன். பிரம்மா-சிவன் முதலிய எல்லா தேவர்களிலிருந்து புல் வரை உள்ள உயிர்களில் அளவில் கூடுதல்-குறைவு இல்லை; ஜீவன் அணு. (மாத்வ கொள்கையில் உயிர்களிடையே வேறுபாடு குணத்தில், அளவில் அல்ல.)",
        '0.8': "ஜீவனுடன் பெருவிரல் நுனி அளவு, பெருவிரல் அளவு, சாண் அளவு, ஜீவ வடிவம் என்ற வடிவங்களால் ஹரி இருக்கிறான்; இத்தகைய எண்ணற்ற வடிவங்களால் எல்லா உறுப்புகளிலும் வியாபித்துக் கருணையுள்ள தேவன் இம்மூவுலகையும் காக்கிறான்.",
        '0.9': "பிம்பமான ஹரி எல்லாரிடத்திலும் பெருவிரல் அளவு ஜீவனுடன், நுண் ஆகாயத்தில், இதயத் தாமரையின் நடுவில் வசிக்கிறான் என்று அறிந்தவர்கள் கூறுகிறார்கள்; உலகைத் தாங்கும் ஆத்மா, ப்ராஜ்ஞன், பக்தர்களின் குடும்பத் தலைவனான அவன் இவ்வாறு வழிபட வல்ல பக்தர்களைக் காக்கிறான்.",
        '0.10': "'புருஷன்' என்ற பெயருடையவன் எல்லா உயிர்களிலும் உடல் வடிவில், புலன்களை இயக்கும் ஹ்ருஷீகேசனாக இருக்கிறான்; துரீயன் என்ற பெயருடைய விஸ்வன் எழுபத்தீராயிரம் நாடிகளுக்குள் இருந்து, தலையில் பன்னிரண்டு விரல் அளவு எஞ்சியிருக்கும்படி (பரவியுள்ளான்). (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.11': "ஜீவ வடிவான உடலின் உள்ளும் புறமும் தானே வியாபித்து, பற்றற்றவனாய் உயிர்கள் செய்யும் செயல்களில் செயல்படுகிறான்; லக்ஷ்மி, பிரம்மா, சிவனின் சேவையை ஏற்று, தீபவண்ண அழகிய மூர்த்தி நடுவில் இருந்து விஸ்வன் முதலிய வடிவங்களால் ஒளிர்கிறது.",
        '0.12': "கருடன், சேஷன், பவன் முதலிய பெயர்களைத் தாங்கி, வாயு வடிவ உடலில் புலன்களை இயக்கும் ஹரியைப் போல, பிரம்மா, வாணி, பாரதி, பரதன் (வாயு) ஆகியோருடன் லிங்க உடலில் உள்ளனர்; மற்ற தேவர்களுக்கு அத்தகைய இருப்பிடம் இல்லை. (இப்பாடலின் பாடம் படிகளில் வேறுபடுகிறது.)",
        '0.13': "இறைவனின் விருப்பப்படி லிங்க உடல் ஜீவனுக்குத் தானியத்தின் உமி போல இடைவெளியுடன் சூழ்ந்து மூடியாக உள்ளது; முற்றிலும் ஜடமான இப்பிரகிருதியின் அதிதேவதை மகாலக்ஷ்மி எனப்படுகிறாள்; விரஜா நதியில் நீராடும் (முக்தியின் எல்லை) வரை அது ஜீவனுடன் ஒட்டியிருக்கும்.",
        '0.14': "பதினாறு கலைகள் கொண்ட (லிங்க) உடல், அநிருத்த வடிவங்களின் நடுவில் சேர்ந்து, ஜீவனை மூடும் இரு மறைப்புகளாக உள்ளன; அசுரர்களைச் சுமை போல விலக்கும் ஜனார்தனன் மூன்று குணங்களுக்குள் இருப்பதால் 'த்ரிவ்ருத்' எனப்படுகிறான். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.15': "ருத்திரன் முதலிய தேவர்களுக்கு அநிருத்தனின் உடலே வீடு; அங்கிருந்து அவர்கள் தம் சொந்தப் பணி செய்வதில்லை; ஸ்தூல உலகில் சினமுற்ற தீய தேவர்கள் ஒருவருடன் ஒருவர் போட்டியிட்டு இருமைச் செயல்களையும் செழிப்புக்கான செயல்களையும் பிராணேசனின் ஆணையால் செய்கின்றனர். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.16': "பூமியில் புண்ணிய க்ஷேத்திரங்கள், தீர்த்தங்களில், பனி, மழை, வசந்த காலங்களில், உடல்-இடம்-காலம் சார்ந்த மூன்று வகை தர்மச் செயல்களில் பிரம்மா முதலிய எல்லா தேவர்களும் குணங்களைத் தாங்கிப் பின்பற்றி, எல்லாரிடமும் அருகிருந்து தம் பணியைச் செய்கின்றனர்.",
        '0.17': "முடியை ஆயிரம் பங்காக்கிய அளவு நுண்ணிய சுஷும்னை உடலின் நடுவில் தலையின் நுனி வரை பரவியுள்ளது; இந்தச் சுஷும்னையில் மேற்கு, வடக்கு, கிழக்கு, தெற்குத் திசைகளில் வஜ்ரம் போன்ற ஒளிரும் மின்னல்கள் உள்ளன.",
        '0.18': "தாமரையில் பிறந்தவனின் அந்த நாடியில் முக்கோண சக்கரம் உள்ளது; அதில் அக்னி மண்டலத்தின் நடுவில் ஸங்கர்ஷணன் என்ற பெயருடையவன் இருக்கிறான்; இழிந்த பாவ புருஷனை நாளும் அழித்து விஞ்ஞானமயனான கருணையுள்ள ஸ்ரீவாஸுதேவன் அருள் செய்கிறான்.",
        '0.19': "நடு நாடியின் நடுவில், இதயத் தாமரையின் அடியில், வாயுவின் பாத மூலத்தின் அருகில் மூலபதி இருக்கிறான்; ஜீவனின் லிங்க உடல் அநிருத்த உடலுடன் இணைந்திருக்கிறது, ருத்திரன் முதலிய எல்லா தேவர்களும் காக்கிறார்கள். (இப்பாடலின் பாடம் தெளிவற்றது.)",
        '0.20': "தண்டின் நடுவிலுள்ள இதயத் தாமரையின் எட்டு இதழ்களில் குயவனின் சக்கரம் போல ஹம்ஸன் என்ற பெயருடையவன் சுழன்று செல்கிறான்; எல்லாக் காலத்திலும் காவலர்களின் சேவையை ஏற்றுக் கருணையுள்ள அவன் அவர்களின் விருப்பங்களை நிறைவேற்றுகிறான்.",
        '0.21': "வாமனன், பரசுராமன், ராமன், கிருஷ்ணன், மத்ஸ்யம், ஹயவதனன், கபிலன், நரசிம்மன் ஆகிய வடிவங்களால் அந்தந்த உயிர்களை மகிழ்வித்து, நித்திய சுகமயனாய் இதயத் தாமரையில் பிம்பன் எனப்பட்டு உறைகிறான்.",
        '0.22': "இந்திரனின் உலகை அடைந்தால் மனம் நல்ல புண்ணிய வழியில் ஈடுபடும்; அக்னியின் வீட்டில் உறக்கம், சோம்பல், பசி, தாகம்; சூரிய புத்திரனின் (யமன்) வீட்டில் கோப ஆவேசம் காணப்படும்; நிர்ருதியில் இருந்தால் பாவங்கள் செய்யப்படும்; அறியாதவர்களுக்கு ஹரி எட்டாதவனாக இருக்கிறான்.",
        '0.23': "வருணனிடம் விளையாட்டு-சிரிப்பு; வாயுவிடம் போக்குவரத்து; சந்திரன்-குபேரனிடம் தர்ம புத்தி பிறக்கும்; சிவனின் ஆலயத்தில் பசு, செல்வம், நிலம், கன்னிகை ஆகியவற்றை ஒரு நாழிகை கூடத் தாமதிக்காமல் தானம் செய்யும் எண்ணம் பிறக்கும்.",
        '0.24': "இதயத் தாமரையில் கேசரங்களில் வைராக்கியம்; லிங்க உடலில் கனவும் ஆழ்ந்த உறக்கமும்; கர்ணிகையில் விழிப்பு நிலை மட்டுமே பிறக்கிறது; சுதர்சனம் முதலிய எட்டு ஆயுதங்களைப் பிடித்து திக்பாலர்களின் வீடுகளில் சஞ்சரித்தபடி ஹரி இத்தகைய புத்திகளை அளிக்கிறான். (இப்பாடலின் பாடம் ஓரளவு தெளிவற்றது.)",
        '0.25': "காயத்ரியால் உணர்த்தப்படும், ஸூத்ரன் என்ற பெயருடைய பிராணபதி (வாயு) உடலில் நிலைத்திருக்க, இதை அறியாமல் கண்ட இடமெல்லாம் மனைவி-மக்களுடன் பூமியில் சுற்றி 'நாங்கள் தினமும் தீர்த்த க்ஷேத்திர யாத்திரை செய்தோம்' என்று பெருமைப்படுகிறார்கள்.",
        '0.26': "நரசிம்ம வடிவில் 'சரீரம்' என்ற பெயராலும், பதினாறு கலைகள் உடைய லிங்கத்தில் 'புருஷன்' என்ற பெயராலும் அழைக்கப்படுகிறான்; அநிருத்தனாகத் தோன்றுகிறான்; சாந்திரமணன் தூண்டும் ப்ரத்யும்னனாக ஸ்தூல உடலில் இருக்கிறான். (இப்பாடலின் பாடம் முழுமையாகச் சரிபார்க்கப்படவில்லை.)",
        '0.27': "உடலின் முதல் தாதுக்களான தோல், சருமம், இறைச்சி, இரத்தம், கொழுப்பு, மஜ்ஜை, எலும்பு ஆகியவற்றில் நாற்பத்தொன்பது மருத்கணங்கள் உள்ளன; நிதனம், ஹிங்காரம் முதலிய சாமகான நாமங்களால் அழைக்கப்படும் ஹரி நாற்பத்தொன்பது வடிவங்களால் தாதுக்களில் இருக்கிறான்.",
        '0.28': "ஏழு தாதுக்களுக்கு வெளியே, அன்னமயம் முதலிய கோசங்களில், காய்ந்த இரும்பிலுள்ள நெருப்பு போல அவற்றால் கறைபடாமல், அந்தந்தப் பெயருக்குரிய அனுபவத்தை அளித்து, தைஜஸன், ப்ராஜ்ஞன், விஸ்வன் என்ற பெயர்களால் கனவு, ஆழ்ந்த உறக்கம், விழிப்பு நிலைகளை அளிக்கிறான்.",
        '0.29': "உடலின் மஜ்ஜையிலும் விரல் கணுக்களின் இடங்களிலும், மூன்று பகுதிகளில் 360 இடங்களில் அறிஞர்கள் 1,080 வடிவங்களை (ஒவ்வோர் இடத்திலும் மூன்று) கூறுகிறார்கள்; ரமாரமணன் அங்கே உடலிலுள்ள தேவர்களுடன் விளையாடுகிறான்.",
        '0.30': "புழு குளவியை (பேசஸ்காரனை) நினைத்து புழுத்தன்மையை விட்டு அதன் வடிவையே அடைந்து அதைப் போல் திரிவது போல, சிறிய உயிர்கள் பக்தியுடன் கைடபாரியைத் தியானித்துப் பிறவிக் காட்டை விரைவில் கடந்து சாரூப்யத்தை (அவன் போன்ற வடிவை) அடைகின்றன.",
        '0.31': "இவ்வுடலில் இறைவனின் வடிவங்களை மறவாமல் அடிக்கு அடி பக்தியுடன் நினைக்கும் பக்தர்களுக்கு கோபதி ஜகந்நாத விட்டலன் எப்போதும் அருகிருந்து அவர்களை அபரோக்ஷ ஞானிகளாக (நேரடி உணர்வு பெற்றவர்களாக) ஆக்கி எக்காலமும் காக்கிறான்.",
      },
    },
    'harikathamrutasara-10': {
      summary: "பத்தாம் சந்தி (ஸர்வ பிரதீகம்): ஹரியை எல்லாவற்றிலும் காண்பவனுக்கு ஒவ்வோர் இடமும் புனிதம், ஒவ்வொரு காலமும் பண்டிகை, ஒவ்வோர் உயிரும் தானத்துக்கு உரியது, ஒவ்வொரு சொல்லும் மந்திரம், ஒவ்வொரு செயலும் பூஜை; கிரகங்களும் தேவர்களும் அவனது தாசர்களுக்கு நன்மை செய்பவர்கள்; அசுரர்களை இயக்கும் தேவர்களும் அவன் ஆணைப்படியே நடக்கிறார்கள். 'நான்-என்னுடையது' என்று ஹரியை நினையாதவனுக்கு நீராடல், தீர்த்த யாத்திரை, துறவு வேடம், பாராயணம், உபவாசம் வீணானவை என்று இச்சந்தி எச்சரிக்கிறது. தன் இதயத்தில் இறைவன் பேச வைத்தபடியே தான் பேசியதாகக் கவி கூறி, இரகசியத்தை பக்தர்களுக்கே சொல்லும்படி வேண்டி, அவதாரங்களின் ஜெய ஸ்துதியுடன் முடிக்கிறான்.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருத ஸாரத்தைக் கூறுகிறேன்; உயர்ந்த பகவத் பக்தர்களே, இதை மரியாதையுடன் கேளுங்கள். (ஒவ்வொரு சந்தியின் தொடக்கத்திலும் பாடப்படும் பல்லவி.)",
        '0.1': "பரப்பிரம்மத்தினும் வேறான பிரம்மா முதலிய தேவர்களும் 'பத்தர்' எனப்படுகிறார்கள்; தினமும் ஹரியின் திருவடிகளைச் சேவிப்பவர்களுக்கு அவர்கள் நன்மை செய்பவர்களே; அவர்களைக் கெடுக்க அவர்களால் இயலுமா? ஸ்ரீவிலாசாஸ்பதனின் தாசர்களுக்குத் தோல்வி உண்டோ?",
        '0.2': "ஸ்ரீதனின் திருவடித் தாமரைகளை அன்புடன் துதிப்பவர்களுக்கு இந்த நவகிரகங்கள் பதினோராம் இடத்தில் இருப்பது போல (மிகவும் நன்மை தருவனவாக) இருக்கும்; தேவர்கள் அவர்களின் மன-உடல் நோய்களை இடைவிடாமல் நீக்கிக் காக்கிறார்கள்; எல்லோரும் ஒன்றாக இறைவனின் ஆணையால் இவ்வாறு செய்கிறார்கள்.",
        '0.3': "அறிந்த யோகிக்குப் பூமியிலுள்ள பசுக்குளம்படித் தண்ணீர் எல்லாம் அழுக்கு போக்கும் தீர்த்தம்; மரங்கள், மலைகள், தரையே புண்ணிய க்ஷேத்திரம்; உயிர்த்தொகை ஸ்ரீதனின் விக்ரஹங்கள்; அவர்கள் அளிக்கும் உணவே நைவேத்தியம்; வழியில் நடப்பதே நடனம்.",
        '0.4': "சிவன் வணங்கும் இறைவனின் தூய வடிவை தியானிப்பவனுக்கு ஒவ்வோர் இடமும் புண்ணிய இடம், ஒவ்வொரு காலமும் பண்டிகைக் காலம், மூவுலகிலும் எல்லா உயிர்களும் தானத்துக்கு உரியவர், எல்லாச் சொற்களும் மந்திரங்கள், எல்லாச் செயல்களும் பூஜை.",
        '0.5': "தெய்வக் குளங்கள், ஏரிகள், கிணறுகள், தடாகங்களின் அபிமான தேவதைகள் உடலின் ரோம துவாரங்களில் நிறைந்துள்ளனர்; கங்கை முதலிய நதிகள் எழுபத்தீராயிரம் நல்ல நாடிகளில் பாய்கின்றன என்று பாவி.",
        '0.6': "மூன்று கோடிக்கும் மேற்பட்ட (ரோம துவாரங்களிலும்) எழுபத்தீராயிரம் நாடிகளிலும் வாயுவின் அந்தர்யாமியான மாதவன் தினமும் விளையாடுகிறான்; இவ்வாறு அறிந்த அறிஞர்களே தேவர்கள், அவர்களின் உடல்களே புண்ணிய க்ஷேத்திரம், அவர்களை அர்ச்சிப்பதே ஹரி பூஜை.",
        '0.7': "நீராடல் ஸ்ரீவரனுக்கு அபிஷேகம் என்று அறிந்த பூமியின் மக்கள் எந்த நீரில் மூழ்கினாலும் கங்கை முதலிய தீர்த்தங்கள் தாமாக வந்து அங்கு நிலைக்கின்றன; இவ்வர்த்தங்களை அறியாத உயிர்கள் தேவ நதியை அடைந்தாலும் பயன் என்ன?",
        '0.8': "பூமியில் கடல் வரை பாயும் நதிகள்-ஓடைகளில் அவன் தன்னைக் காட்டிக்கொள்ளாமல் விளையாடுகிறான்; அறிஞர்கள் விதி-தடைகளைக் கடைப்பிடிக்கிறார்கள்; இறைவனின் வடிவச் சிந்தனை எங்கும் வந்தபோது எல்லாச் செயல்களையும் விட்டுவிடுகிறார்கள்.",
        '0.9': "கலி முதலிய எல்லா அசுரர்களுக்குள்ளும் ஹரியின் ஆணைப்படி பிரம்மா, சிவன் முதலிய தேவர்கள் இயக்குபவர்களாக இருக்கின்றனர், அவர்கள் தங்கள் பாவச் செயல்களைச் செய்தபடி இருக்கின்றனர்; உறுதியான பக்தியும் ஞானமும் நிறைந்தவர்கள் தாமரைக்கண்ணனுக்கு அர்ப்பணித்தபடி அவர்கள் நடுவிலும் சுகமாக இருக்கின்றனர்.",
        '0.10': "எந்த உயிர்களுக்குள் இருந்தாலும், எந்தச் செயலைச் செய்தாலும், எந்த குண-உருவங்களை உபாசித்தாலும், காக்கும் தலைவனால் மிகவும் மதிக்கப்பட்டு, எந்த உலகிலும் அவன் வலிமையால் சஞ்சரிக்கும் தேவர்களை பாவச் செயல்கள் தொட முடியுமா?",
        '0.11': "கணவனுடன் மனம் ஒன்றி தினமும் மகிழ்ந்து மக்களைப் பெற்ற பெண் புலனடக்கியவள் எனப்படுகிறாள்; அவ்வாறே கிருதிபதியின் கதையமுத விருந்தில் ஈடுபட்ட மகாத்மாக்களை, அச்யுதனின் தாசர்களை மற்ற குற்றங்கள் எப்படித் தொடும்?",
        '0.12': "பெருகிய ஆற்றில் தன் துணிவைக் காட்டுவதாகக் குதித்து, கை சோர்ந்து மூழ்குபவனைப் போல, ஹரியை விட்டு, சர்வேசன் விதித்ததைக் கைவிட்டு ஆசையால் பிறரை வழிபடும் மனிதன் துன்பமடைகிறான். (இப்பாடலின் பாடம் ஓரளவே தெளிவு.)",
        '0.13': "'நான்-என்னுடையது' என்ற மந்த புத்தி மனிதன் தினமும் செய்யும் நீராடல், ஜபம், தேவ பூஜை முதலிய செயல்களை அசுரர்கள் கழுவி எடுத்துச் செல்கிறார்கள்; ஸ்ரீநிவாசன் ஏற்பதில்லை; மதயானை பழுத்த விளாம்பழத்தை உண்டது போலாகும்.",
        '0.14': "பூமியின் எல்லாத் தீர்த்த க்ஷேத்திரங்களிலும் திரிந்தால் என்ன? தகுதி-தகுதியின்மை அறியாமல் அன்னம் முதலிய தானம் செய்தால் பயன் என்ன? ஹரி எங்கும் நிறைந்தவன் என்று அறியாமல் தானே கர்த்தா என்பவன் தூய உடலுடன் மந்திர-ஸ்தோத்திரம் ஓதினால் என்ன?",
        '0.15': "கண்ட நீரில் மூழ்கி உடலை வருத்தினால் பயன் என்ன? தண்டம்-கமண்டலம் தாங்கி யதி எனப்பட்டால் பயன் என்ன? பறவைகளின் தலைவனை (கருடனின் நாயகனை) சார்ந்த திருவடித் தாமரையில் மனத்தை இரவும் பகலும் வண்டு போல வைக்காத மனிதன் இன்பம் அடைவதில்லை.",
        '0.16': "வேதம், சாஸ்திரம், புராணக் கதைகளைச் சொன்னால் என்ன? தடை செய்யப்பட்ட செயல்களையெல்லாம் விட்டு நற்செயல்கள் செய்தால் என்ன? உணவை விட்டு உபவாசம் இருந்து மூச்சை அடக்கினால் என்ன, ஆசையும் சினமும் அழியாமல் 'நான்-என்னுடையது' என்னும் மனிதனுக்கு?",
        '0.17': "ஸ்ரீநிவாசனின் பிறப்பு-செயல்களையும் அவன் உருவம்-பெயர்களையும் அந்தந்த இடத்தில் எப்போதும் அன்புடன் நினைக்காதவன் தினமும் எதைக் கேட்டாலும், பார்த்தாலும், படித்தாலும், சொன்னாலும், பாடினாலும், செய்தாலும் என்ன பயன்?",
        '0.18': "இது என் புத்தி, கல்வி, வலிமையால் சொல்லப்பட்ட தூய காவியம் அல்ல; தத்துவங்களின் நல்ல முறைகளை அறிஞர்களிடமிருந்து நன்கு அறிந்த மனிதனும் நான் அல்லன்; மத்வவல்லபனே என் இதயத்தில் இருந்து பேசச் செய்தபடி நான் பேசினேன்; ஆகையால் என் பாடல்களின் குறைகளைப் பாராமல் அறிஞர்கள் செவிசாய்த்துக் கேட்க வேண்டும்.",
        '0.19': "கரும்பிலுள்ள சாறு போன்ற ஹரி சரிதாமிர்தம் செல்வம்-இளமை மயக்கத்தில் தன்னை மறந்தவனுக்குக் கிடைக்காது; ஹரியின் திருவடித் தாமரையில் பொங்கும் நற்பக்தி ரசத்தைப் பருகி, பூரித்து, இன்பக் கடலில் விளையாடுபவனுக்கே அன்றி வேறொருவனுக்குக் கிடைக்காது.",
        '0.20': "கருடக் கொடியோனின் திருவடி பக்தியின் வகைகளை அறியாத மனிதர்களுக்கு இது எப்போதும் விடுகதை போலத் தோன்றும்; முக்குணம் அற்றவனின் தூய குணங்களைப் புகழ்ந்து மகிழும் பாகவதர்களுக்கு அவன் மிகுந்த பக்தி, நல்லறிவு, சுகம் அளித்துக் காக்கிறான்.",
        '0.21': "பரம தத்துவத்தின் இந்த இரகசியத்தை அந்தணர்கள் மரியாதையுடன் கேட்க வேண்டும்; கடுமையானவர்களுக்கும், மூடர்களுக்கும், தன்னைப் பண்டிதன் எனக் கருதுபவர்களுக்கும், தீயவர்களுக்கும், ரசனையற்றவர்களுக்கும் இதைச் சொல்லக்கூடாது; இறைவனின் திருவடித் தாமரையின் வண்டுகள் எனப்படுவோருக்கு எப்போதும் மகிழ்ச்சியுடன் அறிவிக்க வேண்டும்.",
        '0.22': "இது உலகியல் பேச்சு அல்ல; மறுமையின் ஒரே தலைவனின் சொல்லை அவர்கள் கேட்பார்களா? குறுகிய மனமுள்ளவர்களுக்கு இது பொருந்துமா? வண்டு ஏற்பது போல நீரிலுள்ள தவளை தாமரையின் மணத்தை அறிய முடியுமா? இதன் சுவை ஹரி பக்தர்களுக்கே அன்றி வேறு எவருக்கும் இல்லை.",
        '0.23': "(இறைவனை விளித்து:) தனக்கென்று பயன் இல்லாதவனே, எல்லா விருப்பங்களையும் அளிப்பவனே, எல்லா குணங்களும் நிறைந்தவனே, அறியத்தக்கவனே, மூப்பு-மரணம்-துயரம் அற்றவனே, மிக்க ஞானியே, உலகின் ஆத்மாவே, கருணையுள்ளவனே, சூரியனைப் போல ஒளிர்பவனே, எல்லையற்ற மகிமையுடையவனே, நெய் முதலிய பிரதீகங்களால் திருவடித் தாமரைகள் ஆராதிக்கப்படும் தேவராஜனே!",
        '0.24': "மலையைத் தாங்கியவனுக்கு ஜெயம்; நரசிம்ம வேடனுக்கு ஜெயம்; வாமன-த்ரிவிக்ரம தேவனுக்கு ஜெயம்; பிருகுராமனுக்கும் பூமனுக்கும் ஜெயம்; ஜானகியின் நாயகனுக்கு ஜெயம்; ருக்மிணியின் விருப்பம் நிறைவேற்றுபவனுக்கு ஜெயம்; ஜினர்களை மயக்கியவனுக்கு ஜெயம்; கலியை அழிப்பவனுக்கு ஜெயம்; ரமாரமணனுக்கு ஜெய ஜெய.",
        '0.25': "சச்சிதானந்த ஆத்மா, பிரம்மாவும் தேவர்களும் அர்ச்சிக்கும் திருவடித் தாமரைகளை உடையவன், பரம மங்கலன், மத்வரின் அந்தக்கரணத்தில் நிலைத்தவனான அச்யுத ஜகந்நாத விட்டலன் எப்போதும் தனக்குப் பிரியமான மக்களைக் கைவிடமாட்டான்; அவன் காட்டுத் தீயை விழுங்கி காட்டில் பசுக்களையும் இடையர்களையும் காத்தவன்.",
      },
    },
    'harikathamrutasara-11': {
      summary: "பதினோராம் சந்தி (தியானப் பிரக்ரியை): ஜீவன் ஹரிக்கு உட்பட்டவன், ஹரி எல்லாவற்றுக்கும் உள்ளிருந்து தூண்டுபவன் என்பதால் புலன்களிலும் உடல் நாடிகளிலும் ஒவ்வொரு செயல்-அனுபவத்திலும் அவனை எவ்வாறு நினைக்க வேண்டும் என்று இச்சந்தி கூறுகிறது. புலன்கள், சுவைகள், உயிர்கள், ஆண்-பெண்களின் அபிமான தேவதைகளில் அவன் வடிவங்களை விளக்கி, இருவகை வழிபாட்டைப் போதிக்கிறது: வியதிரேகம் (பொருள்களை அவனிடமிருந்து வேறாக அர்ப்பணித்தல்), அன்வயம் (ஒவ்வொரு பொருளிலும் அவனைக் காணுதல், பிம்பத்தை மறக்காதிருத்தல்). விக்ரஹம், உயிர்கள், இயற்கை மலைகளில் வழிபாட்டைக் கூறி, ஹரி சராசரங்களில் முழுமையாக வியாபித்திருப்பதை அறியாதவர்களுக்கு தீர்த்த யாத்திரை, நீராடல், ஜபம், தானம் ஆகியவற்றால் பயனில்லை என்று முடிக்கிறது.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருத ஸாரத்தைக் கூறுகிறேன்; உயர்ந்த பகவத் பக்தர்களே, இதை மரியாதையுடன் கேளுங்கள். (ஒவ்வொரு சந்தியின் தொடக்கத்திலும் பாடப்படும் பல்லவி.)",
        '0.1': "செருப்பிலுள்ள முள், மணல் முதலியவை நாளும் நடப்பவனை வருத்துவது போல பதினொரு புலன்களின் பாவங்களும் வருத்துகின்றன; ஆனால் பதினொரு புலன்களிலும் ஹ்ருஷீகேசனின் வடிவை விடாமல் பக்தியுடன் நினைப்பவன் எத்தனை குற்றங்கள் செய்தாலும் பாவக் குவியல்கள் அவன் முக்தி வழியைத் தடுக்கா. (இப்பாடலின் பாடம் முழுமையாகச் சரிபார்க்கப்படவில்லை.)",
        '0.2': "பகலிலும் அணையாத நந்தா விளக்கு போல வேதத்தால் அறியப்படுபவனைக் கைகூப்பி வழிபடு; நான்கு புருஷார்த்தங்களில் ஒன்றையும் கேட்காதே; ஜகத்துதரன் அளித்ததை உண்; பிராணன், புலன்கள், மனம் முதலியவை இறைவனின் அதீனம் என்று அடிக்கடி நினைத்துக்கொண்டிரு.",
        '0.3': "ஜீவன் சுதந்திரமற்றவன்; ஹரி ஒருவனே முழுச் சுதந்திரன், நித்திய சுகமயன். ஜீவன் ஏழை, கட்டுண்டவன், சிறிதளவு அறிவும் ஆற்றலும் உடையவன், துயருறுபவன், சிறியவன்; உடல் கொண்ட அவனுக்கு ஒரு தலைவன் இருக்கிறான்; ஹரி உலகெங்கும் நிறைந்தவன், செய்பவன், பிரம்மா முதலிய தேவர்களால் துதிக்கப்படும் பிரம்மம்; இவ்வாறு அவனைப் போற்று.",
        '0.4': "விஸ்வன் முதலிய எட்டு வடிவங்களை ஒன்பதால் பெருக்கினால் எழுபத்திரண்டு வடிவங்களாகின்றன, ஒவ்வொன்றும் ஆயிரம் எண்ணிக்கையுடையது; தனித்தனி நாடிகளில் சர்வோத்தமனை அறிவாயாக என்று பீஷ்மர் சாந்தி பர்வத்தில் தர்மபுத்திரனுக்கு உபதேசித்தார்.",
        '0.5': "எட்டு பிரகிருதிகளுக்குள் விஸ்வன் முதலிய எட்டு வடிவங்களால் இருந்து பக்தர்களின் முட்களை நீக்கித் தினமும் காக்கிறான்; விடாத உறவினன் போல வைகுண்டரமணன் தன்னவர்களை முள்ளற்ற நல்ல வழியில் நடத்துகிறான்; தீயவர்களை அடிக்கிறான்.",
        '0.6': "சக்தி முதலிய வடிவங்களால் புலன்களின் அபிமானிகளுக்குள் உறைந்து, அறியாதவர்களுக்கு எட்டாதவனான ஸ்வரமணன் ஸ்தூல விஷயங்களை நாளும் அனுபவிக்கிறான்; இதை அறியாமல் 'நான் அனுபவிக்கிறேன்' என்பவர்கள் நிச்சயமாக நரகங்களையே அனுபவிக்கிறார்கள்; மீண்டும் மீண்டும் பிறவிக் காட்டில் அலைந்து சோர்கிறார்கள்.",
        '0.7': "சுருசி, ருசிர, சுகந்த, சுசி என்ற பெயர்களால் ஆறு சுவைகளில் பன்னிரு வடிவங்களால் ஸ்ரீ-பூ-துர்கையருடன் இருக்கிறான்; எழுபத்தீராயிரம் வாயு வடிவங்களில் மகா பராக்கிரம கர்த்தாவாக நாடிகளுக்குள் இருக்கிறான்.",
        '0.8': "(இறைவனிடம்:) உன்னை எங்கும் நினைப்பவர்கள் செய்யும் பிற செயல்களும் புண்ணியச் செயல்களே, ஐயமில்லை. உன்னை நினையாமல் நீராடல், ஜபம், ஹோமம், அன்னம், ஆடை, யானை, குதிரை, நிலம், செல்வம், தானியம் முதலிய எல்லா தர்மங்களும் செய்தால் பயன் என்ன?",
        '0.9': "விரும்பத்தக்க அனுபவப் பொருள்களில் ஷிபிவிஷ்டன் என்ற பெயரால் தினமும் எல்லா உயிர்களையும் திருப்தி செய்து தானும் நிறைவுற்று, வயிற்றில் உறைந்து புலன்களுக்குச் சாரமான வளர்ச்சி அளித்து, எல்லோருக்கும் பிரியனாய் உயிர்களுக்குத் தெரியாமல் எல்லா விஷயங்களையும் உண்கிறான்.",
        '0.10': "'காரகன்' என்ற பெயருடன் ஞான-கர்மங்களைத் தூண்டுபவனாய் கர்மேந்திரியங்களின் அதிபதிகளுக்குள் உறைந்து செயல்களைக் காட்டுகிறான்; முக்குணமயமான பொருள்களிலுள்ள வடிவங்களின் பெயரால் அழைக்கப்படுகிறான்; தன்னை வெளிக்காட்டாமல் மக்களை மயக்கும் மோகத்தை உண்டாக்குபவன்.",
        '0.11': "பூதங்களில் 'த்ரவ்யன்' எனவும், கர்மேந்திரியங்களில் அழிவற்றவன் எனவும், ஞானேந்திரியங்களில் நற்செயலுடையவன் எனவும் இருக்கிறான்; துதிக்கத்தக்க கர்த்தா, சுகமயன், உலகில் சேவிக்கப்படுபவனும் சேவிப்பவனும் எனப்பட்டு அரணிக் கட்டையிலுள்ள நெருப்பு போல இருக்கிறான்.",
        '0.12': "மனம் முதலிய புலன்களில் வாயுதேவன் 'சுசி' எனப்பட்டு எப்போதும் நிலைத்திருக்கிறான், 'சுசிஷத்ஹோதா' என்று அழைக்கப்படுகிறான்; வாமன-ஹ்ருஷீகேச வடிவங்களால் ஹரி எப்போதும் உடலுக்குள் இருந்து விஷயத்தால் பிறக்கும் இன்பத்தை உயிர்களுக்கு அனுபவிக்கச் செய்கிறான்.",
        '0.13': "தூண்டுபவர்களிலும் தூண்டப்படுபவர்களிலும் ஹரி தானே இருந்து, பகையின்றித் தன் பெயர்-உருவத்தால் எல்லோரையும் தூண்டுகிறான்; தன்னைக் காட்டிக்கொள்ளாமல் எல்லாருக்குள்ளும் இருந்து, கங்கையின் தந்தை எல்லாச் செயல்களையும் தானே செய்து செய்வித்துப் பார்த்துச் சிரிக்கிறான்.",
        '0.14': "ஹரியே முதன்மை இயக்குநர் என்று அறிந்து, புண்ணிய-பாவம், மகிழ்ச்சி-சினம், லாபம்-நஷ்டம், சுகம்-துக்கம் போன்ற இருமைகளை நரகம், பூமி, சுவர்க்கம், முக்தி ஆகியவற்றில் அவன் திருவடிக்குச் சமர்ப்பித்து, புலன்களை இயக்குபவனை எங்கும் நினைத்தபடி இரு.",
        '0.15': "சிறுவன் பலனை எண்ணாமல் தன் விருப்பப்படி செய்து தினமும் மகிழ்வது போல, ஞானத்துடன் விதி-தடைகளைக் கவலையுடன் நோக்காமல் செயல்களைச் செய்; கர்மத்தில் முதன்மையான புருஷேசனிடம் பக்தியை வேண்டு, போற்று.",
        '0.16': "இழப்பு, ஆதாயம், வெற்றி, தோல்வி எதை அளித்தாலும் அனுபவித்து, தினமும் லக்ஷ்மிநிவாசனின் கருணையையே சம்பாத்தியமாகக் கருது; கருணையுள்ள அவன் உடலின் உறவினர் போல உள்ளும் புறமும் இருந்து, ஞானானந்தமயரான தன்னவர்களைப் பேரன்புடன் காக்கிறான்.",
        '0.17': "அந்த பரமன் எல்லாப் புலன்களிலும் வியாபித்து, எல்லா உயிர்களிலும் தெரிவிக்காமல் விஷயங்களை ஏற்கிறான்; பாவமற்ற புராண புருஷன் அருகிருந்து, பல வடிவங்களைத் தாங்கி, தன்னைக் காட்டிக்கொள்ளாமல் செயல்களைச் செய்கிறான்.",
        '0.18': "வானில் செல்வன, நிலத்தில் திரிவன, நீரில் வாழ்வன, இரவில் அலைவன ஆகியவற்றுக்குள் இருந்து அவற்றின் செயல்களைச் செய்கிறான்; பெருமகிமையுடையவனும் மிக நுண்ணியவனுமான அவன் மனத்தில் எத்தனை வகையாக எண்ணினாலும் புலன்களுக்கு விஷயமாவதில்லை; கீசகாரியான (பீமனுக்கு) பிரியன், கவிகள் பாடும் மகாராயன்.",
        '0.19': "ஒரே கோத்திர-பிரவரம் உடையவர்கள் சந்தியாவந்தனம் செய்து, இறுதியில் மக்கள் தத்தம் பெயர்களைப் பெறுவது போல, ஒரே உடலில் இருந்து இகழத்தக்க-இகழத்தகாத செயல்களைச் செய்து செய்வித்து, இந்திரேசன் எல்லா உயிர்களுக்குள்ளும் 'ஈசன்' எனப்படுகிறான்.",
        '0.20': "துருப்பிடித்த இரும்பைத் தீயில் சுட்டுத் தூய்மையாக்குவது போல, நெல்லிலுள்ள அரிசியை இறுதியில் உமியிலிருந்து பிரிப்பது போல, தன்னை மறந்து உரத்த சிரிப்புடன் ஒருமுறை 'விட்டலா!' என்று அழைத்தால் அவன் பாவங்களை ஓட்டி விடுவித்து, அவனைத் தன்னுள் வைத்துக் காக்கிறான்.",
        '0.21': "கடலில் நீர்வாழ் உயிர்கள் தம் விருப்பப்படி தத்தம் இடங்களில் மகிழ்ந்து திரிவது போல, தாமரை நாபனுக்குள் பிரம்மா, சிவன், இந்திரன் முதலிய பல உயிர்க்கூட்டங்கள் எப்போதும் வாழ்கின்றன.",
        '0.22': "வாஸுதேவன் உள்ளும் புறமும் ஒளிர்விப்பவனாய் பிம்பமாக அந்தந்த உருவம்-பெயரில் எங்கும் பிரகாசிக்கிறான்; 'சமன்வயம்' (ஒவ்வொரு பொருளிலும் அவனைக் காணுதல்) எனப்படும் இந்த நல்லுபாசனையைச் செய்பவன் முக்தி நாடுவோருள் சிறந்தவன்; அவன் இப்பூமியில் ஜீவன்முக்தன்.",
        '0.23': "அனுபவப் பொருள்களில் ஏற்ற-ஏற்காத சுவைகளை அறிந்து, ஏற்றவர்-ஏற்காதவர் அனைவரிடமும் உறையும் ஹரிக்கு தினமும் சமர்ப்பி; செல்வம் அல்லது வறுமை வந்தபோது பூரிக்காமல், குன்றிச் சோராமல், நற்பக்தி-வைராக்கியம்-ஞானத்தை வேண்டு; நீ துர்ப்பாக்கியசாலி எனப்படாதே.",
        '0.24': "நிலம், நீர், மலைகளில் விளையும் பழம், நல்ல மலர்கள், மணம், சாறு, ஸ்ரீதுளசி முதலிய எல்லா பூஜைப் பொருள்களையும் கங்கையின் தந்தைக்கு பலவகையாக நாளும் அர்ப்பணிப்பதை அறிஞர்கள் 'வியதிரேக பூஜை' (பொருள்களை அவனிடமிருந்து வேறாக அர்ப்பணித்தல்) என்கிறார்கள்.",
        '0.25': "ஸ்ரீகரனை எங்கும் கண்டு, குணம்-உருவம்-செயல்களை அவனுடையவை எனக் கண்டு, வியதிரேகத்தை மட்டும் அறிந்து நின்றுவிடாமல், பிம்பனை மறக்காமல் அன்வயம் செய் (ஒவ்வொரு பொருளிலும் அவனைக் காண்); கருணையுள்ளவன் மறுக்காமல் அருளுடன் ஏற்று, பக்தர்களின் துயரங்களை நீக்கி சுகம் அளித்து இடைவிடாமல் காக்கிறான்.",
        '0.26': "வியதிரேகம், அன்வயம் எனப்படும் இந்த பூஜை முறைகளை அறிந்து தேவேசனை இடைவிடாமல் திருப்தி செய்தபடி இரு; பெருமகிமையுடையவன் இதை ஏற்று நிலை-மரணம்-பிறவிகளை நீக்கி, சேவகர்களைத் தன்னுள் வைத்து மகிழ்விக்கும் பக்தவத்சலன்.",
        '0.27': "தாமரை நாபனுக்குப் பூமியில் ஜடம், சேதனம் என இருவகைச் சிலைகள் உள்ளன; சேதனத்தில் ஆண்-பெண் என இரண்டு; ஜடத்தில் மனிதர் நிறுவிய விக்ரஹம், இயற்கை மலைகள் என இரண்டு என்று அறி; பிரதீகத்தில் பதினைந்தின் அழகிய தொகுப்பை அறிந்து வழிபட்டுவா. (இறுதி வரி தெளிவற்றது.)",
        '0.28': "பிரம்மா, வாயு, இந்திரன், சிவன், நாகேசன், ஸ்மரன், அகங்கார அதிபதி, பிராணன் முதலியோர் ஆண்களின் உடல்களின் அபிமானிகளாகி, தன்னைக் காட்டிக்கொள்ளாத, குற்றமற்ற அநிருத்த நாராயணனின் வடிவை வழிபட்டுச் சுகம் அளிக்கிறார்கள்.",
        '0.29': "ஸ்ரீ, சரஸ்வதி, பாரதி, சௌபர்ணி, வாருணி, பார்வதி முதலியோர் பெண்களுக்குள் அபிமான தேவியர்; அருண வண்ணமுள்ள ஸங்கர்ஷண-ப்ரத்யும்ன வடிவங்களை இரவும் பகலும் உபாசித்து மகிழ்கிறார்கள்.",
        '0.30': "நிறுவப்பட்ட பிரதீகங்களில் (பிரதிஷ்டை செய்த விக்ரஹங்களில்) பார்கவன், அக்னி, வாயு முதலிய தேவர்கள் அபிமானிகளாக நிலைத்து துதிக்கப்பட்டு, தினமும் துளசி, சந்தனம், அட்சதை, மலர், பழம், தீபம், பஞ்சாமிர்தத்தால் வழிபடும் பக்தர்களுக்குப் புருஷார்த்தங்களை அளிக்கிறார்கள்.",
        '0.31': "இயற்கை மலைகளின் அபிமான தேவர்கள் தம் தலைவனான ஸ்ரீவாஸுதேவனை வழிபடுகிறார்கள்; உள்ளார்ந்த பேதம் அற்றவனை நான்கு வகை பிரதீகங்களில் அறிந்து வழிபட்டால் பிறவிக் கடலைக் கடக்கச் செய்து முக்தர்களாக்குகிறான்.",
        '0.32': "எந்த க்ஷேத்திரத்துக்குச் சென்றால் என்ன? எந்தத் தீர்த்தத்தில் மூழ்கினால் என்ன? எந்த ஜபம், தவம், ஹோமம், தானம் செய்தால் என்ன பயன், ஸ்ரீவர ஜகந்நாத விட்டலன் இந்தச் சராசர உயிர்களுக்குள் முழுமையாக நிறைந்திருக்கிறான் என்று அறியாத மனிதர்களுக்கு.",
      },
    },
    'harikathamrutasara-12': {
      summary: "பன்னிரண்டாம் சந்தி (நாடீ பிரகரணம்): உடலில் எழுபத்தீராயிரம் நுண் நாடிகள் உள்ளன, ஒவ்வொரு பக்கமும் முப்பத்தாறாயிரம், நூறு ஆண்டுகளின் பகல்-இரவுகள் அளவு; அவற்றில் ஹரி லக்ஷ்மியுடன் எண்ணற்ற வடிவங்களில் இருந்து, பிரம்மா, வாயு, அந்தந்த அபிமான தேவர்களின் சேவையை ஏற்கிறான். புண்ணிய நதிகள் இந்நாடிகளில் பாய்கின்றன, ஞானிகள் அங்கே நாளும் நீராடுகிறார்கள். அறிந்தவன் செய்வதெல்லாம் ஹரி பூஜை, ஹரி எல்லா உயிர்களிலும் இருந்தும் அவற்றின் குற்றங்கள் தீண்டாதவன் என்று இச்சந்தி போதிக்கிறது; நூற்றுப்பதினாறு ஆண்டு வாழ்க்கையை மூன்று ஸவனங்களின் யாகமாக வர்ணிக்கிறது; வாயுதேவன் ஹம்ஸ மந்திர ஜபமாகச் செய்யும் மூச்சுகளை எண்ணுகிறது; இறைவன் பேச வைத்தபடியே பேசினேன் என்ற கவியின் கூற்றுடன் முடிகிறது.",
      verses: {
        '0.0': "குருவின் கருணையால் ஹரிகதாம்ருத ஸாரத்தைக் கூறுகிறேன்; உயர்ந்த பகவத் பக்தர்களே, இதை மரியாதையுடன் கேளுங்கள். (ஒவ்வொரு சந்தியின் தொடக்கத்திலும் பாடப்படும் பல்லவி.)",
        '0.1': "வாஸுதேவன் பிராணன் முதலிய தத்துவ அதிபதிகளின் சேவையை ஏற்று, இவ்வுடலிலுள்ள முப்பத்தாறாயிரம் நல்ல நாடிகளுக்குள் ஸ்ரீ, பூமி தேவியருடன் விளையாடுகிறான்; அந்தப் பரமேசனின் தூய அழகிய வடிவங்களைச் சிந்தித்து மகிழ்ந்திரு.",
        '0.2': "கால்களில் பன்னிரண்டாயிரம், நடு உடலில் பதினான்காயிரம், கைகளில் நான்காயிரம், தலையில் ஆறாயிரம் நாடிகள் உள்ளன. இவ்வாறு சிந்தித்து, இரவு-பகலின் அபிமான தேவர்களை அறிந்து உபாசிப்பவர்கள் பூமியில் இருந்தும் சுவர்க்கவாசிகளே.",
        '0.3': "'ப்ருஹதி' என்ற பெயருடைய, குற்றமற்ற வாஸுதேவன் ஆண்-பெண்களின் எழுபத்தீராயிரம் நாடிகளில் இருந்து, பிரம்மா முதலிய தேவகணங்களால் போற்றப்பட்டு, பெருமகிமையும் பெருங்கருணையும் உடையவனாய் எல்லா உயிர்களையும் இடைவிடாமல் காக்கிறான்.",
        '0.4': "நூறு ஆண்டுகளுக்கு முப்பத்தாறாயிரம் நாள்கள்; உடலில் நாடிகளும் அவ்வளவே என்று அறிந்து ஒரு நாள் அறிஞர்களைப் போற்றியவன் ஒவ்வொரு நாளும் தம்பதிகளின் அர்ச்சனையைச் செய்தவனே; இது உண்மை, ஒருபோதும் ஐயமில்லை.",
        '0.5': "இருபத்துநான்கு தத்துவங்களும் அவற்றின் அதிபதிகளான பிரம்மா முதலிய தேவர்களும் தினமும் ஒவ்வொரு நாடியிலும் இருந்து, பதினான்கு உலகங்களிலும் உயிர்த் தொகுதிகளைக் காக்கும் நிலையானவனை அந்தந்த இடத்தில் கண்டு மகிழ்கிறார்கள்.",
        '0.6': "சத்திய சங்கல்பனான ஹரி எழுபத்தீராயிரம் நாடிகளில் 34,56,000 வடிவங்களால் சித்-பிரகிருதியுடன் (லக்ஷ்மியுடன்) இருக்கிறான்; பரம நித்திய மங்கல மூர்த்தியான அவன் பக்தர்களுக்கு நெருங்கிய உறவினனாய் எங்கும் காக்கிறான்.",
        '0.7': "மணிகளுக்குள் உள்ள நூல் போல பிரணவத்தால் உணர்த்தப்படுபவன் எல்லா சேதனக் கூட்டங்களிலும் இருந்து தன்னவர்களை இடைவிடாமல் காக்கிறான்; வணங்குவோரின் விருப்பம் அளிப்பவன், பக்தர்களின் சிந்தாமணி, சித்-ஆனந்தமே உடலாக உடையவன்; அணுவிலும் பெரியதிலும் இருந்து சிறியவன் போல உறைகிறான்.",
        '0.8': "சுஷும்னை முதலிய எல்லா நாடிகளின் கோசம் நாபி மூலத்தில், விருஷண ஆசனத்தின் நடுவில் 'துந்தி' என்ற பெயரில் உள்ளது. பிரம்மா முதலியோர் மூலேசனின் ஆனந்தம் முதலிய நற்குணங்களை உபாசித்தபடி உடல்களுக்குள் இருக்கிறார்கள்.",
        '0.9': "அறிஞர்கள் கவனிக்க வேண்டும்: பாகீரதி முதலிய தீர்த்தங்கள் எழுபத்தீராயிரம் நாடிகளில் உள்ளன. இந்த இரகசியத்தை அற்பர்களுக்குக் காட்டிச் சொல்லாமல் உறுதியுள்ளவர்கள் தினமும் நாடி நதிகளில் நீராடி மகிழ்கிறார்கள்.",
        '0.10': "இவ்வுடலின் இட-வல நாடிகளில் தேவர்கள் உள்ளனர் என்று அறி: பிரம்மா, வாயு, வாணி முதலியோர் வலப்புறம்; சேஷன், கருடன், சிவன், ஆறு மகிஷிகள், வாருணி, இந்திரன், காமன் முதலியோர் இடப்புறம் உள்ளனர்.",
        '0.11': "இரு பக்க நாடிகளிலும் தேவர்களுடன் விளையாடியபடி, கருடவாகனன் உயிர்களின் தகுதிக்கேற்ற சாதனையைச் செய்து செய்வித்து பக்தர்களை அன்புடன் காக்கிறான்; அசுரர்களுக்கு வெற்றி கிடைக்க விடாமல் அவர்களின் நற்புண்ணியங்களைப் பறிக்கிறான்.",
        '0.12': "துந்தியிலிருந்து தலை வரை ஒரே நாடி பரவியுள்ளது; அதனுள் தாமரையில் பிறந்த பிரம்மா இருக்கிறார்; அதற்குப் பத்துக் கிளைகள்; பதினொரு புலன்கள் அங்கே இணைந்துள்ளன; சூரியன், சந்திரன், வருணன், அஸ்வினிகள் முதலியோர் அங்கே எப்போதும் நிலைத்துள்ளனர்.",
        '0.13': "தொப்புளிலிருந்து ஒரே நாடி வளையாமல் நேராக நடு உடலில் 'சுஷும்னை' என்ற பெயரில் உள்ளது. அரக்கர்களை உள்ளே புக விடாமல், வாயுதேவன் பத்துத் திசைகளிலும் வேறு எவரையும் பொருட்படுத்தாமல் உடலில் சஞ்சரிக்கிறான்.",
        '0.14': "இத்தனை நாடிக் கிளைகள் இவ்வுடலில் உள்ளன; ஒரே ஆத்மாவான நாராயணன் எழுபத்தீராயிரம் வடிவினனாகி நாடிகளில் தன் துணைவியுடன் இரவும் பகலும் இவ்வாறு பிரம்மாண்டத்தின் எல்லா உயிர்களிலும் இருந்து மயக்குகிறான்.",
        '0.15': "நாளுக்கு நாள் வளரும் சந்திரனின் கதிர்களின் அழகைக் குருடன் கண்டு மகிழ முடியுமா? கீழ்மகனுக்கு இந்த நற்கதை அமுத விருந்தின் இன்பம் கிடைக்குமா? லக்ஷ்மியின் மனங்கவர்ந்தவனின் நற்குணங்களைப் பாடும் பக்தனுக்கே அன்றி வேறொருவனுக்குக் கிடைக்காது.",
        '0.16': "இவ்வுடலில் நாடிகள் நெசவின் பாவும் ஊடும் போலப் பின்னியுள்ளன; இந்திரன் முதலியோர் தம்மினும் உயர்ந்தோருடன் அங்கிருந்து, அசுரர்களை அச்சுறுத்தி, 'சந்தாதா' என்ற பெயருடைய ஹரியின் குணங்களில் அன்புடன் நல்லுபாசனை செய்து மகிழ்கிறார்கள்.",
        '0.17': "நீர்வாழ்வன, கோழி, பறவை முதலிய உயிர்களின் உடல்களில் இருந்து தன்னைக் காட்டாமல், அந்தந்த உருவ-பெயர்களால் அழைக்கப்பட்டு, தாமரைக்கண்ணன் பலவகைச் செயல்களை இடைவிடாமல் செய்து செய்வித்து, அவற்றின் பலன்களை உண்ணாமல் நித்திய சுகம் நிறைந்தவனாய்ச் சஞ்சரிக்கிறான். (இப்பாடலின் பாடம் முழுமையாகச் சரிபார்க்கப்படவில்லை.)",
        '0.18': "இவ்வாறு அறிந்து உபாசனை செய்தபடி, அழுக்கானவன் போல இருந்து தீயவர்களின் கண்ணில் படாமல், அறிஞர்களிடம் கர்வம் கொள்ளாமல், மழை, வெயில், பசி, தாகம், வெற்றி-தோல்வி, தீயோரின் இகழ்ச்சி-புகழ்ச்சி, அச்சங்களுக்கு அஞ்சாமல் மதயானை போலப் பூமியில் சஞ்சரி.",
        '0.19': "காட்டிலும் ஊரிலும் உள்ள எல்லா உயிர்களும் தினமும் செய்யும் எச்செயலும் ஹரி பூஜையே என்று அறிந்து, நற்பக்தியுடன் தியானித்து, வாயு முதலிய தேவர்களின் அந்தராத்மாவான ஸ்ரீநிவாசனுக்கு அர்ப்பணித்து மகிழ்ந்து களித்திரு.",
        '0.20': "காண்பதற்கு இனியவன் உலகில் நாய், பன்றி முதலியவற்றிலும் உறைகிறான்; இரண்டற்ற ஒருவனான அவன் பல உருவ-பெயர்களால் அழைக்கப்பட்டு உள்ளிருந்தும் தெரிவிப்பதில்லை; ஸ்ரீ, பிரம்மா முதலிய எல்லா தேவகணங்களாலும் ஆராதிக்கப்பட்டு ஏற்றுக்கொண்டு தினமும் காக்கிறான்.",
        '0.21': "இவ்வாறு உபாசிக்கும் நல்லோர் உலக வாழ்வில் தினந்தோறும் எதைச் செய்தாலும் அது எல்லாம் ஹரி பூஜை எனப்படும்; இது உண்மை. இச்சொல்லில் ஐயம் கொள்ளும் மனிதன் அற்பனே; அவன் புறச் சடங்குகளைச் செய்து பயன் என்ன? (இப்பாடலின் பாடம் முழுமையாகச் சரிபார்க்கப்படவில்லை.)",
        '0.22': "அனுபவிக்கப்படுவனவற்றிலும் அனுபவிப்பவர்களிலும் ஹரி தானே அனுபவப் பொருளும் அனுபவிப்பவனும் எனப்பட்டு, தக்க-தகாத சுவைகளைத் தேவ-அசுர கூட்டங்களுக்கு ஊட்டுகிறான். பாக்கிய நிதியான அவன் பக்தர்களுக்கு நல்ல வைராக்கியம், பக்தி, ஞானம் அளிக்கிறான்; தகுதியற்றவர்களுக்குத் தன்னிடம் வெறுப்பு முதலியவற்றை அளிக்கிறான்.",
        '0.23': "இப்பதினான்கு உலகங்களில் சராசர உயிர்களில் நாளும் உறைந்து, விரோசனன் மகனை (பலியை) ஏமாற்றியவன் 'யாசகன்' எனப்படுகிறான்; மாரீசனை அடக்கியவன் அழகிய ஹம்ஸ வடிவில் 'நிஷேசகன்' என்ற பெயருடன் மக்களின் விருப்பங்களை நிறைவேற்றுகிறான்.",
        '0.24': "அன்னம் அளிப்பவன், அன்னம் உண்பவன், அன்னமயன், தானே அன்னம்; பிரம்மா முதலிய எல்லா உயிர்களுக்கும் அநிருத்தன் முதலிய வடிவங்களால் உணவை அமைக்கிறான்; பிறரை எதிர்பாராமல் குண-கருணைக் கடலான அவன் படைக்கிறான்; ஹிரண்யகர்ப்பனுக்குள் இருந்து மூவுலகையும் காக்கிறான்.",
        '0.25': "மூன்றடியான், தேவர்களின் தலைவன், மூன்று இடங்களில் உறைபவன், மூவழி நதியின் (கங்கையின்) தந்தை, த்ரிவிக்ரமன், எளியோரிடம் அன்புடையவன், நீலத்தாமரை இதழ் போலக் கரியவன், எல்லையற்றவன், அளவற்ற சித்-சுக-குணங்களே உடலாக உடையவன், வைகுண்டம் முதலிய உலகங்களின் அதிபதி, மூவேத வடிவினன் தன்னவர்களைக் கபடமின்றிக் காக்கிறான்.",
        '0.26': "உப்பு கலந்த நீர் நாவுக்கு உப்பாகவே தோன்றும்; பார்ப்பவர்களால் அதைப் பிரித்துக் காட்ட முடியுமா? அவ்வாறே தன்வயத்தனும் எங்கும் பரவியவனுமான லக்ஷ்மீநாதன் சராசரங்களில் நிறைந்திருக்கிறான்; அறியப்படாத அவனை முழுமையாக அறிந்தவர் தேவர்களில் யார்?",
        '0.27': "சின்மயனான அவன் வியாபிக்கப்படுவது போல எல்லா உயிர்களுக்குள்ளும் இருக்கிறான்; கொடிய சம்சாரத்தால் வெந்தவர்கள் பக்தியுடன் வழிபட்டால் இம்மையிலும் மறுமையிலும் அடையத்தக்கவனாகிறான்; பக்தவத்சலன் அவர்களின் குறைகளைப் பொறுத்து, பிறப்பு முதலிய குற்றங்களை அவர்களுக்கு எப்போதும் விலக்குகிறான்.",
        '0.28': "பலவகையில் ஹரியை மகிழ்வித்து மனத்தில் நிறுத்தி, எந்த வேலை செய்தாலும் அது அவன் திருவடி பூஜை என்று நினைத்தபடி இரு; கலப்பையேந்தியின் தம்பியான கிருஷ்ணன் தானே எல்லா இடங்களிலும் உறைந்து அசையாத பக்தி, நல்லறிவு, நற்பேறு அளித்துக் காக்கிறான்.",
        '0.29': "குற்றத்தின் வாசனையும் அற்றவன், பலவேடம் பூண்பவன், மூவுலகையும் பேணுபவன், பழமையான புருஷன், இந்திரன் முதலியோரால் துதிக்கப்படுபவன், சேஷசயனன், விபீஷணனுக்குப் பிரியன், விஜயனின் (அர்ஜுனனின்) தோழன் தன்னை மகிழ்விக்கும் மக்களுக்கு விரும்பியவற்றை நிறைவேற்றுகிறான்.",
        '0.30': "'ஸ்ரீயும் பூமியும் சேவிக்கும் திருவடித் தாமரை உடையவனே, எல்லையற்றவனே, நற்பக்தியால் மட்டுமே அடையத்தக்கவனே, பிரம்மா முதலிய தேவர்களும் அசுரர்களும் அர்ச்சிக்கும் திருவடிகளை உடையவனே, அழகனே, வாமனா, ராமா, பிறவி நோய்க்கு மருந்தே, என் குலதெய்வமே, காத்தருள்!' என்று அழைத்தால் கருணையுள்ளவன் வந்து உதவுகிறான்.",
        '0.31': "அசுரர்களிலும் தேவர்களிலும் இருந்து அவரவருக்கேற்பச் செயல்களைச் செய்கிறான்; பிறப்பு-இறப்பு முதலிய எல்லாக் குற்றங்களுக்கும் அப்பாற்பட்ட அவன் நம்முடன் பிறக்கிறான், வாழ்கிறான், செல்வத்தைக் காக்கும் பாம்பு போல எக்காலமும் காக்கிறான்; காரணம் வேண்டாத உறவினன் அவன்.",
        '0.32': "சூரியன் வானில் உதிக்கும்போது மரங்களின் நிழல்கள் பூமியில் பரவுகின்றன; மறையும்போது அங்கேயே ஒடுங்குகின்றன. அவ்வாறே இம்மூவுலகும் வாயு முதலிய முதன்மைத் தேவர்களின் அந்தராத்மாவின் வசத்தில் உள்ளன; அவன் அவற்றைத் தன் வயிற்றில் வைத்துக்கொண்டு எல்லாச் செயல்களையும் பார்ப்பவர்களுக்குக் காட்டுகிறான்.",
        '0.33': "மூவுலகுக்கும் ஒரே ஆராதனைக்குரியவன், லக்ஷ்மியின் அழகிய தோள்களால் தழுவப்பட்டவன், தானே தோன்றியவன், சுகாத்மா, பொன்னிறத்தான், கருடவாகனன், அபயம் அளிப்பவன், எண்ணற்ற சூரிய-சந்திரர் போல ஒளிர்பவன், களங்கமற்றவன் தன்னை நாளும் வணங்குவோருக்கு எல்லா நன்மைகளையும் தாமதமின்றி அளிக்கிறான்.",
        '0.34': "அறிஞர்களிடமிருந்து அறி: காலை, நண்பகல், மாலை ஸவனங்கள் வசுக்கள், ருத்திரர், ஆதித்யர்களுக்கு உரியவை; அவர்களில் ஒளிரும் வாயுவுக்குள் க்ருதி, ஜயா, மாயா ஆகியோரின் நாயகனின் (ப்ரத்யும்னன், ஸங்கர்ஷணன், வாஸுதேவன்) மூன்று மூர்த்திகளைச் சிந்தித்து, நாள்கள் என்ற ஆஹுதிகளால் அர்ச்சித்து மகிழ்ந்திரு.",
        '0.35': "இருபத்துநான்கு ஆண்டுகள் வசு தேவர்களில் ப்ரத்யும்னன் இருக்கிறான்; நாற்பத்துநான்கு ஆண்டுகள் ஸங்கர்ஷணன் எனப்படுபவன் நெருப்புக்கண்ணனான ருத்திரனில் இருக்கிறான்; நாற்பத்தெட்டு ஆண்டுகள் வெண்ணிற உடலுடைய மாயாபதி (வாஸுதேவன்) ஆதித்யனில் இருக்கிறான்.",
        '0.36': "நூற்றுப்பதினாறு ஆண்டுகளில் நூற்றுப்பதினாறு அழகிய வடிவங்களால் வசு, ருத்திர, ஆதித்யர்களில் துணைவியுடன் விளையாடுகிறான்; நாணமின்றி வழிபடும் பக்தர்களை வருத்தும் பாவ வெள்ளங்களை வெகுதூரம் ஓட்டி, பயம் போக்குபவன் விடாமல் அருகிலேயே உறைகிறான்.",
        '0.37': "83,520 வடிவங்களால் பகல்-இரவுகளின் அதிபதிகளில் நாளும் தோன்றுகிறான்; பாரதி-பிராணனுக்குள் இருந்து பக்தர்களின் பாவங்களை விலக்கி, ஹிங்காரம், நிதனம் முதலிய வடிவங்களால் பித்ருக்களைக் காக்கிறான்.",
        '0.38': "மிகச் சிறந்த தூய கம்பளி ஆடையை வேண்டுமென்றே சேற்றில் தோய்த்து எடுத்தால், சோதித்துப் பார்க்கையில் சேறு ஒட்டுமா? பத்மநாபன் எல்லா உயிர்களிலும் இருந்தாலும் முக்குணங்களால் கட்டுண்பானா? அவன் நித்திய சுகாத்மா, சின்மயன்.",
        '0.39': "எல்லாக் குற்றங்களுக்கும் அப்பாற்பட்டவன், ஆயிரக்கணக்கான சந்திரர், அக்னிகள், எண்ணற்ற சூரியர் கூட்டம் போல ஒளிரும் உடலுடையவன், லக்ஷ்மியின் கணவன், தேவர்களின் நண்பன்; பிரம்மாண்டத்திலுள்ள பிரம்மா முதலிய எல்லா சேதனக் கூட்டத்துக்கும் தானே தோழன் எனப்பட்டு, வஞ்சகமற்றவனாய் அவர்களைப் போலவே இருக்கிறான்.",
        '0.40': "வெவ்வேறு இடங்களில் உள்ள ஆகாயம் போல அவன் உயிர்த் தொகுதியில் எந்த இடைவெளியும் இன்றி எப்போதும் உறைகிறான்; ஸ்ரீயுடன் எங்கும் ஆகாயம் இடம் தருவது போலத் தந்து, எதையும் எதிர்பாராமல் அனைவரின் அந்தராத்மா சுகம் அளிப்பவனாய் ஒளிர்கிறான்.",
        '0.41': "ஸ்ரீ, பிரம்மா முதலிய தேவகணங்கள் சேவிக்கும் திருவடித் தாமரை உடையவன் இந்த ஜட-ஜீவ தொகுதிகளின் உள்ளும் புறமும் எப்போதும் உறைந்து, 'இடமுடையவன்' எனப்பட்டு, தன் உடலிலேயே அவற்றை வைத்துக்கொண்டு பேணுகிறான்; அவன் தேவன், தேவகியை மகிழ்விப்பவன், அசுரரை அழிப்பவன், மரணத்தை வென்றவன்.",
        '0.42': "ஒரு மாதத்துக்கு, தினசரிக் கணக்குப்படி, மூச்சுகள் 6,48,000 ஆகின்றன; ஹம்ஸன் என்ற பெயருடைய ஹரியை நூற்றுப்பதினாறு ஆண்டுகள் இவற்றால் வழிபட்டால் கருணைக்கடல் குசேலனிடம் மகிழ்ந்தது போல நாள்தோறும் மகிழ்கிறான்.",
        '0.43': "ஸ்தூல உடலில் இருந்து வாயுதேவன் கருணையால் ஓர் ஆண்டுக்கு 77,76,000 மூச்சு ஜபங்களைப் பதினான்கு உலகங்களிலுள்ள உயிர்த் தொகுதியில் செய்கிறான்; அவன் மூவுலகிலும் பரவியவன், மிக நெருங்கியவன்.",
        '0.44': "நான்கு உடல்களில் இருந்து வாயுதேவன் மூவகை உயிர்களுக்குள் நாளொன்றுக்கு 86,400 மூச்சு ஜபங்களைச் செய்கிறான்; பவனராயன் மீது கரனின் பகைவனின் (ராமனின்) கருணை வலிமை எத்தகையதோ!",
        '0.45': "ஸ்ரீயின் நாயகனான ஜகந்நாத விட்டலன் கருணையுடன் என் வாயில் பேசியபடியே நான் பேசினேன், வேறல்ல; அறிஞர்களே, கேளுங்கள். சாதுக்களின் அடையாளத்தை மட்டும் காட்டுபவர்கள் இதை மறுத்தால் என்ன? இதில் என் குற்றம் என்ன என்பதை அறிஞர்கள் ஆராய்ந்து சொல்லட்டும்.",
      },
    },
  },
};
